// ===== hidden judge =====
public static class __Judge
{
    private static void Run(string id, System.Func<string> body)
    {
        string reason;
        try { reason = body(); }
        catch (System.Exception e) { reason = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    private static System.Action Updater(SkillTargetingManager manager)
    {
        var method = typeof(SkillTargetingManager).GetMethod("Update",
            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public);
        if (method == null) throw new System.MissingMethodException("Update");
        return (System.Action)System.Delegate.CreateDelegate(typeof(System.Action), manager, method);
    }

    private static UnityEngine.Transform Enemy(SkillTargetingManager manager, float x)
    {
        var enemy = new UnityEngine.GameObject().transform;
        enemy.position = new UnityEngine.Vector3(x, 0f, 0f);
        manager.RegisterEnemy(enemy);
        return enemy;
    }

    public static void Main()
    {
        Run("empty-list-null", () =>
        {
            var m = new SkillTargetingManager(); var update = Updater(m);
            update();
            return m.CurrentTarget == null ? null : "적이 없는데 타깃이 null이 아님";
        });
        Run("nearest-in-range", () =>
        {
            var m = new SkillTargetingManager(); var update = Updater(m);
            Enemy(m, 7f); var near = Enemy(m, 3f); Enemy(m, 5f); Enemy(m, 30f);
            update();
            return object.ReferenceEquals(m.CurrentTarget, near) ? null : "가장 가까운 적이 선택되지 않음";
        });
        Run("out-of-range-null", () =>
        {
            var m = new SkillTargetingManager(); var update = Updater(m);
            Enemy(m, 9f); Enemy(m, -20f);
            update();
            return m.CurrentTarget == null ? null : "사거리(8) 밖의 적이 선택됨";
        });
        Run("range-boundary-inclusive", () =>
        {
            var m = new SkillTargetingManager(); var update = Updater(m);
            Enemy(m, 8.5f); var edge = Enemy(m, 8f);
            update();
            return object.ReferenceEquals(m.CurrentTarget, edge) ? null : "거리가 사거리(8)와 정확히 같은 적이 선택되지 않음";
        });
        Run("inactive-skipped", () =>
        {
            var m = new SkillTargetingManager(); var update = Updater(m);
            var a = Enemy(m, 2f); var b = Enemy(m, 4f);
            a.gameObject.SetActive(false);
            update();
            if (!object.ReferenceEquals(m.CurrentTarget, b)) return "비활성 적을 건너뛰지 않음";
            b.gameObject.SetActive(false);
            update();
            return m.CurrentTarget == null ? null : "전원 비활성인데 타깃이 null이 아님";
        });
        Run("tie-keeps-first", () =>
        {
            var m = new SkillTargetingManager(); var update = Updater(m);
            Enemy(m, 6f); var first = Enemy(m, 5f); Enemy(m, -5f); Enemy(m, 5f);
            update();
            return object.ReferenceEquals(m.CurrentTarget, first) ? null : "거리가 같을 때 리스트에서 앞선 적이 선택되지 않음";
        });
        Run("zero-alloc-update", () =>
        {
            var m = new SkillTargetingManager(); var update = Updater(m);
            for (int i = 0; i < 16; i++) Enemy(m, 20f - i);
            Enemy(m, -5f);
            for (int i = 0; i < 300; i++) update(); // warm-up
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int i = 0; i < 200; i++) update();
            long after = System.GC.GetAllocatedBytesForCurrentThread();
            long perFrame = (after - before) / 200;
            return after == before ? null : "Update가 프레임당 약 " + perFrame + " B를 할당함";
        });
    }
}

