public static class __Judge
{
    private static void Run(string id, System.Func<string> body)
    {
        string reason;
        try { reason = body(); }
        catch (System.Exception e) { reason = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    public static void Main()
    {
        Run("exact-zero-expiry", () =>
        {
            var t = new CooldownTimer(4); var buf = new int[4];
            if (!t.TryStart(1, 0.5f)) return "TryStart가 false를 반환함";
            if (t.Tick(0.25f, buf) != 0 || t.GetRemaining(1) != 0.25f) return "0.25초 후 남은 시간이 0.25가 아님";
            int n = t.Tick(0.25f, buf);
            if (n != 1 || buf[0] != 1) return "남은 시간이 정확히 0이 된 틱에 만료 보고되지 않음";
            if (t.IsOnCooldown(1) || t.ActiveCount != 0 || t.GetRemaining(1) != 0f) return "만료 후에도 항목이 남아 있음";
            if (t.Tick(0.25f, buf) != 0) return "이미 만료된 스킬이 다시 보고됨";
            return null;
        });
        Run("restart-rejected", () =>
        {
            var t = new CooldownTimer(4); var buf = new int[4];
            t.TryStart(2, 3f); t.Tick(1f, buf);
            if (t.TryStart(2, 10f)) return "쿨다운 중인 스킬의 TryStart가 true를 반환함";
            if (t.GetRemaining(2) != 2f || t.ActiveCount != 1) return "거부된 TryStart가 상태를 바꿈";
            if (t.TryStart(3, 0f) || t.TryStart(3, -1f) || t.TryStart(3, float.NaN)) return "0 이하 또는 NaN duration이 허용됨";
            if (t.ActiveCount != 1) return "잘못된 duration이 항목을 추가함";
            return null;
        });
        Run("capacity-full", () =>
        {
            var t = new CooldownTimer(3); var buf = new int[3];
            if (t.Capacity != 3) return "Capacity가 생성자 인자와 다름";
            if (!(t.TryStart(1, 1f) && t.TryStart(2, 2f) && t.TryStart(3, 3f))) return "용량 이내의 TryStart가 실패함";
            if (t.TryStart(4, 1f)) return "가득 찬 상태의 TryStart가 true를 반환함";
            if (t.ActiveCount != 3 || t.IsOnCooldown(4) || t.GetRemaining(2) != 2f) return "가득 찬 상태의 TryStart가 기존 상태를 바꿈";
            if (t.Capacity != 3) return "용량이 늘어남";
            return null;
        });
        Run("huge-delta-expires-all-once", () =>
        {
            var t = new CooldownTimer(4); var buf = new int[4];
            t.TryStart(2, 1f); t.TryStart(3, 2f); t.TryStart(4, 3f); t.TryStart(5, 4f);
            int n = t.Tick(float.MaxValue, buf);
            if (n != 4) return "만료 보고 개수가 4가 아님: " + n;
            System.Array.Sort(buf, 0, n);
            if (buf[0] != 2 || buf[1] != 3 || buf[2] != 4 || buf[3] != 5) return "누락되거나 중복된 ID가 있음";
            if (t.ActiveCount != 0) return "만료 후 ActiveCount가 0이 아님";
            if (t.Tick(1f, buf) != 0) return "다음 틱에 다시 보고됨";
            if (!t.TryStart(9, 1f)) return "만료 후 빈 자리를 재사용하지 못함";
            return null;
        });
        Run("remove-while-iterating", () =>
        {
            var t = new CooldownTimer(4); var buf = new int[4];
            t.TryStart(10, 1f); t.TryStart(11, 1f); t.TryStart(12, 5f); t.TryStart(13, 1f);
            int n = t.Tick(1f, buf);
            if (n != 3) return "동시에 만료된 3개 중 일부가 누락되거나 중복됨: " + n;
            System.Array.Sort(buf, 0, n);
            if (buf[0] != 10 || buf[1] != 11 || buf[2] != 13) return "보고된 ID가 잘못됨";
            if (t.ActiveCount != 1 || !t.IsOnCooldown(12)) return "살아남아야 할 항목이 사라짐";
            if (t.GetRemaining(12) != 4f) return "살아남은 항목이 정확히 한 번 틱되지 않음: " + t.GetRemaining(12);
            return null;
        });
        Run("non-positive-delta-ignored", () =>
        {
            var t = new CooldownTimer(2); var buf = new int[2];
            t.TryStart(1, 4f);
            if (t.Tick(0f, buf) != 0 || t.Tick(-1f, buf) != 0 || t.Tick(float.NaN, buf) != 0) return "0·음수·NaN deltaTime에서 만료가 보고됨";
            if (t.GetRemaining(1) != 4f) return "0·음수·NaN deltaTime이 남은 시간을 바꿈";
            if (t.Tick(4f, buf) != 1 || buf[0] != 1) return "이후 정상 틱에서 만료되지 않음";
            return null;
        });
        Run("cancel", () =>
        {
            var t = new CooldownTimer(3); var buf = new int[3];
            t.TryStart(1, 1f); t.TryStart(2, 2f); t.TryStart(3, 3f);
            if (!t.Cancel(1)) return "Cancel이 false를 반환함";
            if (t.Cancel(1)) return "이미 취소된 스킬의 Cancel이 true를 반환함";
            if (t.ActiveCount != 2 || t.IsOnCooldown(1)) return "Cancel 후 상태가 잘못됨";
            if (t.GetRemaining(2) != 2f || t.GetRemaining(3) != 3f) return "Cancel이 다른 항목을 손상시킴";
            if (t.Tick(1f, buf) != 0 || t.GetRemaining(3) != 2f) return "Cancel 후 틱 결과가 잘못됨";
            return null;
        });
        Run("zero-alloc", () =>
        {
            var t = new CooldownTimer(32); var buf = new int[32];
            long allocated = 0;
            for (int round = 0; round < 60; round++)
            {
                bool measured = round >= 30; // first 30 rounds are warm-up
                long before = System.GC.GetAllocatedBytesForCurrentThread();
                for (int i = 0; i < 40; i++) t.TryStart(i, 0.1f + i * 0.01f);
                t.Cancel(3);
                for (int f = 0; f < 100; f++) { t.Tick(0.016f, buf); t.IsOnCooldown(f); t.GetRemaining(f); }
                long after = System.GC.GetAllocatedBytesForCurrentThread();
                if (measured) allocated += after - before;
            }
            return allocated == 0 ? null : "측정 구간에서 " + allocated + " B가 할당됨";
        });
    }
}

