using System;

/// <summary>
/// Fixed-capacity pool for plain C# objects (not thread-safe).
/// </summary>
public sealed class ObjectPool<T> where T : class
{
    // Inactive instances are packed in [0, _count) and used as a stack.
    // Allocated once in the constructor, never resized.
    private readonly T[] _items;
    private readonly Func<T> _factory;
    private readonly Action<T> _reset;
    private int _count;

    /// <summary>
    /// factory creates a new instance when the pool is empty (must not be null).
    /// reset is called on every accepted Return (may be null: then nothing is called).
    /// maxSize is the maximum number of inactive instances kept (must be at least 1).
    /// prewarmCount instances are created with factory right away (0..maxSize); reset is not called for them.
    /// Throws ArgumentNullException for a null factory and ArgumentOutOfRangeException for a bad maxSize or prewarmCount.
    /// </summary>
    public ObjectPool(Func<T> factory, Action<T> reset, int maxSize, int prewarmCount = 0)
    {
        if (factory == null) throw new ArgumentNullException(nameof(factory));
        if (maxSize < 1) throw new ArgumentOutOfRangeException(nameof(maxSize));
        if (prewarmCount < 0 || prewarmCount > maxSize) throw new ArgumentOutOfRangeException(nameof(prewarmCount));

        _factory = factory;
        _reset = reset;
        _items = new T[maxSize];
        for (int i = 0; i < prewarmCount; i++)
        {
            _items[_count++] = factory();
        }
    }

    /// <summary>Maximum number of inactive instances the pool keeps.</summary>
    public int MaxSize => _items.Length;

    /// <summary>Number of instances currently waiting inside the pool.</summary>
    public int CountInactive => _count;

    /// <summary>
    /// Returns a stored instance when one is available (factory is not called);
    /// otherwise creates a new one with factory.
    /// </summary>
    public T Rent()
    {
        if (_count == 0) return _factory();

        _count--;
        T item = _items[_count];
        _items[_count] = null; // the pool must not keep a reference to an object that is in use
        return item;
    }

    /// <summary>
    /// Gives an instance back.
    /// - null: throws ArgumentNullException.
    /// - the same instance is already waiting in the pool: throws InvalidOperationException
    ///   (reset is not called, nothing changes).
    /// - otherwise reset is called exactly once, then the instance is stored and true is returned;
    ///   when the pool already holds MaxSize instances it is dropped instead and false is returned.
    /// </summary>
    public bool Return(T item)
    {
        if (item == null) throw new ArgumentNullException(nameof(item));

        // Double-return check: O(CountInactive), by reference, before anything is changed.
        for (int i = 0; i < _count; i++)
        {
            if (ReferenceEquals(_items[i], item))
                throw new InvalidOperationException("This instance is already in the pool.");
        }

        if (_reset != null) _reset(item);

        if (_count == _items.Length) return false; // full: drop it, the GC reclaims it

        _items[_count++] = item;
        return true;
    }
}

