using System;

public static class HudFormat
{
    /// <summary>
    /// Writes totalSeconds as "MM:SS" into buffer, starting at index 0,
    /// and returns the number of chars written.
    /// - Minutes use at least two digits and more when needed: 754 -> "12:34", 6000 -> "100:00".
    /// - Seconds always use two digits. A negative totalSeconds is treated as 0 ("00:00").
    /// - buffer is never null and has at least 16 elements (the caller guarantees it).
    /// Does not allocate: digits are written straight into the caller's buffer.
    /// </summary>
    public static int WriteTimer(int totalSeconds, char[] buffer)
    {
        if (totalSeconds < 0) totalSeconds = 0;

        int minutes = totalSeconds / 60;
        int seconds = totalSeconds % 60;

        // How many digits do the minutes need? At least two ("05"), more from 100 minutes on.
        int minuteDigits = 2;
        for (int m = minutes / 100; m > 0; m /= 10) minuteDigits++;

        // Digits come out lowest first, so fill the minute field from right to left.
        int rest = minutes;
        for (int i = minuteDigits - 1; i >= 0; i--)
        {
            buffer[i] = (char)('0' + rest % 10);
            rest /= 10;
        }

        buffer[minuteDigits] = ':';
        buffer[minuteDigits + 1] = (char)('0' + seconds / 10);
        buffer[minuteDigits + 2] = (char)('0' + seconds % 10);
        return minuteDigits + 3;
    }
}

