public static class __Judge
{
    private static void Run(string id, System.Func<string> body)
    {
        string reason;
        try { reason = body(); }
        catch (System.Exception e) { reason = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    private static ActiveList<int> Make(int capacity, params int[] values)
    {
        var list = new ActiveList<int>(capacity);
        foreach (int v in values) list.Add(v);
        return list;
    }

    private static string Join(ActiveList<int> list)
    {
        var sb = new System.Text.StringBuilder();
        foreach (int v in list) { if (sb.Length > 0) sb.Append(','); sb.Append(v); }
        return sb.ToString();
    }

    private static string Expect(ActiveList<int> list, string expected)
    {
        string got = Join(list);
        return got == expected ? null : "기대 [" + expected + "], 결과 [" + got + "]";
    }

    public static void Main()
    {
        Run("empty", () => Expect(Make(4), "") ?? Expect(Make(0), ""));
        Run("index-order", () => Expect(Make(8, 5, 3, 9, 1), "5,3,9,1") ?? Expect(Make(1, 42), "42"));
        Run("after-swap-remove", () =>
        {
            var list = Make(8, 10, 20, 30, 40, 50);
            list.RemoveAtSwapBack(1);
            list.RemoveAtSwapBack(3);
            string err = Expect(list, "10,50,30");
            if (err != null) return "5개 추가 후 1번, 3번 제거: " + err;
            list.RemoveAtSwapBack(0); list.RemoveAtSwapBack(0); list.RemoveAtSwapBack(0);
            return Expect(list, "");
        });
        Run("nested-foreach-independent", () =>
        {
            var list = Make(4, 1, 2, 3);
            var sb = new System.Text.StringBuilder();
            foreach (int a in list)
                foreach (int b in list)
                    sb.Append(a * 10 + b).Append(' ');
            string expected = "11 12 13 21 22 23 31 32 33 ";
            return sb.ToString() == expected ? null : "같은 리스트의 중첩 foreach: 기대 [" + expected + "], 결과 [" + sb + "]";
        });
        Run("modified-during-foreach-throws", () =>
        {
            var list = Make(8, 1, 2, 3);
            bool thrown = false; int seen = 0;
            try { foreach (int v in list) { seen++; if (seen == 1) list.Add(99); } }
            catch (System.InvalidOperationException) { thrown = true; }
            if (!thrown) return "순회 중 Add 후에도 InvalidOperationException이 나지 않음 (본문 실행 " + seen + "회)";
            if (seen != 1) return "순회 중 Add 직후의 MoveNext에서 던져야 함: 본문 실행 " + seen + "회";
            thrown = false;
            try { foreach (int v in list) list.RemoveAtSwapBack(0); }
            catch (System.InvalidOperationException) { thrown = true; }
            if (!thrown) return "순회 중 RemoveAtSwapBack 후에도 InvalidOperationException이 나지 않음";
            return Expect(list, "99,2,3");
        });
        Run("through-ienumerable-interface", () =>
        {
            System.Collections.Generic.IEnumerable<int> seq = Make(8, 7, 8, 9);
            var sb = new System.Text.StringBuilder();
            foreach (int v in seq) sb.Append(v).Append(' ');
            System.Collections.IEnumerable legacy = Make(8, 4, 5);
            foreach (object o in legacy) sb.Append((int)o).Append(' ');
            return sb.ToString() == "7 8 9 4 5 " ? null : "IEnumerable<T>, IEnumerable로 순회: 기대 [7 8 9 4 5 ], 결과 [" + sb + "]";
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(4242);
            var list = new ActiveList<int>(64);
            var model = new System.Collections.Generic.List<int>();
            for (int step = 0; step < 3000; step++)
            {
                if (model.Count < 64 && (model.Count == 0 || rng.Next(100) < 55))
                {
                    int v = rng.Next(1000); list.Add(v); model.Add(v);
                }
                else
                {
                    int i = rng.Next(model.Count);
                    list.RemoveAtSwapBack(i);
                    model[i] = model[model.Count - 1]; model.RemoveAt(model.Count - 1);
                }
                int k = 0;
                foreach (int v in list)
                {
                    if (k >= model.Count || model[k] != v) return step + "번째 연산 뒤 " + k + "번째 요소가 참조 구현과 다름";
                    k++;
                }
                if (k != model.Count) return step + "번째 연산 뒤 요소 수: 기대 " + model.Count + ", 결과 " + k;
            }
            return null;
        });
        Run("zero-alloc-foreach", () =>
        {
            var list = new ActiveList<long>(512);
            long expected = 0;
            for (int i = 0; i < 500; i++) { list.Add(i * 7919L); expected += i * 7919L; }
            long allocated = 0, total = 0;
            for (int round = 0; round < 400; round++)
            {
                bool measured = round >= 200; // first 200 rounds are warm-up
                long before = System.GC.GetAllocatedBytesForCurrentThread();
                foreach (long v in list) total += v;
                long after = System.GC.GetAllocatedBytesForCurrentThread();
                if (measured) allocated += after - before;
            }
            if (total != 400 * expected) return "할당 측정 중 합계가 잘못됨: " + total;
            return allocated == 0 ? null : "측정 구간(foreach 200회)에서 " + allocated + " B가 할당됨";
        });
    }
}

