// ===== hidden judge =====
public static class __Judge
{
    // In-memory stand-in for a save file that counts how it is flushed and closed.
    private sealed class ProbeStream : System.IO.MemoryStream
    {
        public int DisposeCalls;
        public int FlushCalls;
        public override void Flush() { FlushCalls++; base.Flush(); }
        protected override void Dispose(bool disposing) { if (disposing) DisposeCalls++; base.Dispose(disposing); }
        public string Text { get { return System.Text.Encoding.UTF8.GetString(ToArray()); } }
    }

    private static void Settle()
    {
        System.GC.Collect(); System.GC.WaitForPendingFinalizers(); System.GC.Collect(); System.GC.WaitForPendingFinalizers();
    }

    private static void Run(string id, System.Func<string> body)
    {
        string reason;
        try { Settle(); reason = body(); }
        catch (System.Exception e) { reason = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    private static System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, int>> Entries(params object[] keysAndValues)
    {
        var list = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, int>>();
        for (int i = 0; i < keysAndValues.Length; i += 2)
            list.Add(new System.Collections.Generic.KeyValuePair<string, int>((string)keysAndValues[i], (int)keysAndValues[i + 1]));
        return list;
    }

    private static string Show(string s) { return "\"" + s.Replace("\n", "\\n") + "\""; }

    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    private static void UseAndDispose(ProbeStream probe)
    {
        using (var writer = new SaveWriter(probe)) { writer.WriteEntry("hp", 10); }
    }

    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    private static void UseAndForget(ProbeStream probe)
    {
        var writer = new SaveWriter(probe);
        writer.WriteEntry("hp", 10);
    }

    public static void Main()
    {
        Run("save-writes-entries-and-closes", () =>
        {
            int open = SaveWriter.OpenCount;
            var probe = new ProbeStream();
            SaveGame.Save(probe, Entries("hp", 10, "mp", 5, "gold", -3));
            if (probe.Text != "hp=10\nmp=5\ngold=-3\n") return "저장 내용: 기대 " + Show("hp=10\nmp=5\ngold=-3\n") + ", 결과 " + Show(probe.Text);
            if (probe.DisposeCalls == 0) return "Save가 끝났는데 스트림이 닫히지 않음";
            if (SaveWriter.OpenCount != open) return "Save 후 OpenCount 변화: 기대 0, 결과 " + (SaveWriter.OpenCount - open);
            var empty = new ProbeStream();
            SaveGame.Save(empty, Entries());
            return empty.Text == "" && empty.DisposeCalls > 0 ? null : "항목이 0개인 저장: 내용이 비어 있고 스트림이 닫혀야 함";
        });
        Run("save-failure-reaches-caller", () =>
        {
            var probe = new ProbeStream();
            try { SaveGame.Save(probe, Entries("hp", 10, null, 5, "gold", 3)); }
            catch (System.ArgumentNullException) { return null; }
            return "키가 null인 항목이 있는데 ArgumentNullException이 호출자에게 전달되지 않음";
        });
        Run("stream-closed-when-save-fails", () =>
        {
            int open = SaveWriter.OpenCount;
            var probe = new ProbeStream();
            try { SaveGame.Save(probe, Entries("hp", 10, null, 5, "gold", 3)); } catch (System.ArgumentNullException) { }
            if (probe.DisposeCalls == 0) return "두 번째 항목에서 예외가 난 뒤 스트림이 닫히지 않음";
            if (SaveWriter.OpenCount != open) return "저장 실패 후 OpenCount 변화: 기대 0, 결과 " + (SaveWriter.OpenCount - open);
            return probe.Text == "hp=10\n" ? null : "실패 전까지 쓴 내용: 기대 " + Show("hp=10\n") + ", 결과 " + Show(probe.Text);
        });
        Run("double-dispose-is-a-no-op", () =>
        {
            int open = SaveWriter.OpenCount;
            var probe = new ProbeStream();
            var writer = new SaveWriter(probe);
            if (SaveWriter.OpenCount != open + 1) return "생성 직후 OpenCount 변화: 기대 +1, 결과 " + (SaveWriter.OpenCount - open);
            writer.WriteEntry("hp", 1);
            writer.Dispose();
            if (SaveWriter.OpenCount != open) return "Dispose 1회 후 OpenCount 변화: 기대 0, 결과 " + (SaveWriter.OpenCount - open);
            writer.Dispose(); writer.Dispose();
            if (SaveWriter.OpenCount != open) return "Dispose 3회 후 OpenCount 변화: 기대 0, 결과 " + (SaveWriter.OpenCount - open);
            System.GC.KeepAlive(writer);
            return probe.DisposeCalls > 0 && probe.Text == "hp=1\n" ? null : "Dispose 후 스트림이 닫혀 있고 내용이 " + Show("hp=1\n") + "이어야 함";
        });
        Run("write-after-dispose-throws", () =>
        {
            var probe = new ProbeStream();
            var writer = new SaveWriter(probe);
            writer.Dispose();
            try { writer.WriteEntry("hp", 1); }
            catch (System.ObjectDisposedException) { return probe.Text == "" ? null : "Dispose 후의 WriteEntry가 내용을 씀"; }
            return "Dispose 후 WriteEntry가 ObjectDisposedException을 던지지 않음";
        });
        Run("gc-after-dispose-changes-nothing", () =>
        {
            int open = SaveWriter.OpenCount;
            var probe = new ProbeStream();
            UseAndDispose(probe);
            int disposeCalls = probe.DisposeCalls, flushCalls = probe.FlushCalls;
            Settle();
            if (SaveWriter.OpenCount != open) return "using으로 닫은 writer가 GC된 뒤 OpenCount 변화: 기대 0, 결과 " + (SaveWriter.OpenCount - open);
            if (probe.DisposeCalls != disposeCalls || probe.FlushCalls != flushCalls) return "using으로 닫은 writer가 GC될 때 스트림을 다시 건드림";
            return null;
        });
        Run("gc-of-forgotten-writer-leaves-stream-alone", () =>
        {
            var probe = new ProbeStream();
            UseAndForget(probe);
            Settle();
            if (probe.DisposeCalls != 0 || probe.FlushCalls != 0)
                return "Dispose하지 않은 writer가 GC될 때 종료자가 스트림을 건드림 (Flush " + probe.FlushCalls + "회, Dispose " + probe.DisposeCalls + "회)";
            return probe.Text == "hp=10\n" ? null : "내용: 기대 " + Show("hp=10\n") + ", 결과 " + Show(probe.Text);
        });
    }
}

problems.scenario:
모바일 RPG 클라이언트에서 코루틴으로 짜 둔 네트워크·로딩 코드를 async/await로 옮기는 PR을 리뷰하고 있습니다. 작성자는 PR 설명에 "`await`는 그 작업을 백그라운드 스레드에서 기다렸다가 돌아오는 문법이라 메인 스레드를 막지 않는다"고 적었습니다.

```csharp
// (1) 퀘스트 보상 창의 [받기] 버튼 클릭 핸들러
public async void OnClaimClicked()
{
    Reward reward = await _api.ClaimRewardAsync(_questId);   // 서버 왕복 수백 ms
    _inventory.Add(reward);
    _rewardPopup.Show(reward);                               // 보상 창의 UI
}

// (2) 아이콘 캐시: 호출의 대부분은 캐시에서 바로 끝난다
public async ValueTask<Sprite> GetIconAsync(int id)
{
    if (_icons.TryGetValue(id, out Sprite icon)) return icon;
    icon = await _loader.LoadIconAsync(id);
    _icons[id] = icon;
    return icon;
}

// (3) "설정이 바뀌었다"는 푸시를 받으면 다음 프레임에 다시 받는다
void Update()
{
    if (_configDirty) { _config = _api.LoadConfigAsync().Result; _configDirty = false; }
}
```

QA 보고는 세 가지입니다.

1. 서버 점검 중에 [받기]를 누르면 오류 안내가 뜨지 않는다. 버튼을 호출하는 쪽을 try/catch로 감쌌는데도 예외가 잡히지 않는다.
2. 응답이 오기 전에 보상 창을 닫으면, 응답이 온 뒤 닫힌 창의 UI를 건드리다 예외가 난다.
3. 설정 푸시를 받은 순간 화면이 멈추고 다시 움직이지 않는다.

**질문: async 메서드는 컴파일되면 무엇이 되고, `await` 한 줄에서는 어떤 일이 어떤 순서로 일어납니까? 이를 바탕으로 (a) Task와 ValueTask를 고르는 기준, (b) async void에서 던져진 예외가 가는 곳, (c) 취소를 전달하고 받는 방법을 설명하고, QA 보고 1·2·3을 각각 어떻게 고치겠습니까?**

(.NET 8 / C# 12 기준으로 답하고, 언어 명세가 정한 것과 런타임·라이브러리 구현이 하는 일을 구분해 주세요. Unity와 UniTask에 대해서는 Unity 매뉴얼과 UniTask README에 적힌 범위에서만 답합니다.)

followUps.keyAnswer:
- **토큰은 두 개, 역할이 다르다.**
  - 보상 지급 요청은 서버의 상태를 바꾼다. 창을 닫았다고 이 요청의 응답을 버리면, 서버는 지급했는데 클라이언트 인벤토리에는 없는 상태가 된다. 그래서 요청에는 창이 아니라 **세션(로그인) 수명** 토큰을 넘긴다.
  - 창 토큰은 **닫힌 창의 UI를 건드리지 않기 위한 것**이다. 창을 열 때 `CancellationTokenSource`를 만들고, 닫을 때 `Cancel()`한 뒤 `Dispose()`한다. 문서도 다 쓴 소스는 Dispose하라고 한다.
- **await 뒤에 다시 확인한다.** TAP 문서에 따르면 실행 중에 취소를 요청해도 작업은 그 요청을 받아들이지 않을 수 있고, 그러면 결과나 예외로 끝난다. 그래서 "토큰을 넘겼으니 됐다"가 아니라, 응답을 받은 뒤 UI를 만지기 직전에 창 토큰을 본다.

```csharp
public async void OnClaimClicked()                 // 이벤트 핸들러만 async void, 본문은 얇게
{
    CancellationToken popupToken = _popupCts.Token;
    try
    {
        await ClaimAsync(popupToken);
    }
    catch (OperationCanceledException) when (popupToken.IsCancellationRequested)
    {
        // 창이 닫혀서 멈춘 것: 오류가 아니므로 안내하지 않는다
    }
    catch (Exception e)
    {
        if (!popupToken.IsCancellationRequested) _errorDialog.Show(e.Message);
    }
}

private async Task ClaimAsync(CancellationToken popupToken)
{
    Reward reward = await _api.ClaimRewardAsync(_questId, _sessionToken);
    _inventory.Add(reward);                        // 데이터는 창과 상관없이 반영
    popupToken.ThrowIfCancellationRequested();     // 닫힌 창의 UI만 건너뛴다
    _rewardPopup.Show(reward);
}
```

- **왜 이렇게 동작하는가.**
  - `ThrowIfCancellationRequested`가 던진 예외를 `ClaimAsync` 안에서 잡지 않으면, 반환 작업은 canceled 상태가 된다(명세 §15.14.3). 그 작업을 await한 핸들러는 `OperationCanceledException`(또는 파생 예외)을 받는다(TAP 문서).
  - `when (popupToken.IsCancellationRequested)` 필터를 붙이면 **내가 요청한 취소만** 조용히 넘긴다. 라이브러리 내부 사정으로 생긴 취소 예외까지 삼키지 않는다. 취소 문서도 예외의 토큰을 보고 협조적 취소인지 다른 예외 상황인지 가리라고 설명한다.
  - 진짜 오류(점검 중 등)는 핸들러의 `catch`에서 한 번만 안내한다. 보고 1이 고쳐진다.
  - async void를 남긴 이유: 버튼 이벤트는 void를 요구하고, 문서도 async void를 이벤트 핸들러 용도로 둔다. 핸들러 바깥으로 예외가 새지 않도록 핸들러 안에서 모두 처리했다.
- **UniTask라면(README).** `async UniTaskVoid` 핸들러에 `.Forget()`을 쓰고, 토큰은 `GetCancellationTokenOnDestroy()`(Unity 2022.2 이상은 `destroyCancellationToken`)로 얻을 수 있다. README의 예제처럼 `catch (Exception ex) when (!(ex is OperationCanceledException))`로 취소를 걸러 내거나, `SuppressCancellationThrow()`로 예외 대신 `(IsCanceled, Result)` 튜플을 받을 수 있다. README는 이 방법이 취소 예외를 던지고 잡는 비용을 피하는 용도라고 설명한다.

