using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

/// <summary>
/// Game-time delay (the game clock, not the wall clock). The returned task completes once
/// <paramref name="delay"/> of game time has passed, or ends Canceled if <paramref name="ct"/>
/// is canceled first.
/// </summary>
public interface IDelayProvider
{
    Task Delay(TimeSpan delay, CancellationToken ct);
}

/// <summary>One step of the dungeon entry sequence (map, monster table, sound bank...).</summary>
public interface ILoadStep
{
    string Name { get; }

    /// <summary>
    /// Loads this step. Well-behaved steps end Canceled soon after <paramref name="ct"/> is
    /// canceled, but some third-party steps ignore the token.
    /// </summary>
    Task LoadAsync(CancellationToken ct);

    /// <summary>Releases what LoadAsync loaded. Only valid after LoadAsync succeeded. Never throws.</summary>
    void Unload();
}

public sealed class DungeonLoader
{
    private readonly IReadOnlyList<ILoadStep> _steps;
    private readonly IDelayProvider _delay;
    private readonly TimeSpan _timeout;

    public DungeonLoader(IReadOnlyList<ILoadStep> steps, IDelayProvider delay, TimeSpan timeout)
    {
        _steps = steps ?? throw new ArgumentNullException(nameof(steps));
        _delay = delay ?? throw new ArgumentNullException(nameof(delay));
        _timeout = timeout;
    }

    /// <summary>
    /// Runs the steps in order. Ends RanToCompletion when every step succeeded,
    /// Canceled when <paramref name="cancel"/> is canceled, faulted with TimeoutException when
    /// the timeout passes, or faulted with the failing step's own exception.
    /// See the scenario for the full contract.
    /// </summary>
    public async Task RunAsync(CancellationToken cancel)
    {
        // Already canceled: end Canceled without starting a step or a timer.
        cancel.ThrowIfCancellationRequested();

        // One token for every step. The player cancels it through the link; the timeout and
        // the end of the run cancel it explicitly (finally).
        using CancellationTokenSource stop = CancellationTokenSource.CreateLinkedTokenSource(cancel);

        // The whole sequence shares one game-time budget. The delay listens to the same token,
        // so it completes normally only on a real timeout and ends Canceled otherwise.
        Task timeout = _delay.Delay(_timeout, stop.Token);

        var loaded = new List<ILoadStep>(_steps.Count);
        try
        {
            foreach (ILoadStep step in _steps)
            {
                Task load;
                try { load = step.LoadAsync(stop.Token); }
                catch (Exception e) { load = Task.FromException(e); }   // a synchronous throw is a failed step

                if (await Task.WhenAny(load, timeout) != load)
                {
                    // Timed out, or canceled by the player, while this step was still running.
                    // Do not wait for it: a step that ignores its token would hold the run hostage.
                    _ = ReleaseWhenDoneAsync(step, load);
                    if (cancel.IsCancellationRequested) throw new OperationCanceledException(cancel);
                    throw new TimeoutException("Dungeon loading did not finish within " + _timeout + ".");
                }

                await load;          // rethrows the step's own exception unchanged
                loaded.Add(step);
            }
        }
        catch
        {
            // Roll back in reverse order: later steps may depend on earlier ones.
            for (int i = loaded.Count - 1; i >= 0; i--) loaded[i].Unload();
            throw;
        }
        finally
        {
            // Releases the pending timeout delay and tells an abandoned step to stop.
            stop.Cancel();
        }
    }

    // An abandoned step may still finish later. If it succeeds, what it loaded must be released;
    // if it fails, the exception is observed here and dropped.
    private static async Task ReleaseWhenDoneAsync(ILoadStep step, Task load)
    {
        try { await load; }
        catch { return; }
        step.Unload();
    }
}

