// ===== hidden judge =====
// Game time is a fake clock advanced by the judge; steps complete only when the judge says so.
// Nothing here depends on wall-clock time except the 1-second upper bound of each wait.
public static class __Judge
{
    sealed class FakeClock : IDelayProvider
    {
        sealed class Pending { public System.TimeSpan Due; public System.Threading.Tasks.TaskCompletionSource Tcs; }
        readonly System.Collections.Generic.List<Pending> _pending = new System.Collections.Generic.List<Pending>();
        public System.TimeSpan Now;
        public readonly System.Collections.Generic.List<System.TimeSpan> Requested = new System.Collections.Generic.List<System.TimeSpan>();
        public int PendingCount { get { lock (_pending) return _pending.Count; } }
        public System.Threading.Tasks.Task Delay(System.TimeSpan delay, System.Threading.CancellationToken ct)
        {
            lock (_pending) Requested.Add(delay);
            if (ct.IsCancellationRequested) return System.Threading.Tasks.Task.FromCanceled(ct);
            var p = new Pending { Due = Now + delay, Tcs = new System.Threading.Tasks.TaskCompletionSource() };
            lock (_pending) _pending.Add(p);
            ct.Register(() => { lock (_pending) _pending.Remove(p); p.Tcs.TrySetCanceled(ct); });
            return p.Tcs.Task;
        }
        public void Advance(double seconds)
        {
            Now += System.TimeSpan.FromSeconds(seconds);
            while (true)
            {
                Pending due = null;
                lock (_pending) foreach (var p in _pending) if (p.Due <= Now && (due == null || p.Due < due.Due)) due = p;
                if (due == null) return;
                lock (_pending) _pending.Remove(due);
                due.Tcs.TrySetResult();
            }
        }
    }

    sealed class FakeStep : ILoadStep
    {
        public string Name { get; set; }
        public bool IgnoresToken, CompletesSync;
        public System.Exception ThrowsSync;
        public System.Threading.Tasks.TaskCompletionSource Tcs;
        public System.Threading.CancellationToken Token;
        public int Loads, Unloads;
        public System.Collections.Generic.List<string> Log;
        public System.Threading.Tasks.Task LoadAsync(System.Threading.CancellationToken ct)
        {
            Loads++; Token = ct;
            lock (Log) Log.Add("load " + Name);
            if (ThrowsSync != null) throw ThrowsSync;
            if (CompletesSync) return System.Threading.Tasks.Task.CompletedTask;
            Tcs = new System.Threading.Tasks.TaskCompletionSource();
            if (!IgnoresToken) ct.Register(() => Tcs.TrySetCanceled(ct));
            return Tcs.Task;
        }
        public void Unload() { Unloads++; lock (Log) Log.Add("unload " + Name); }
    }

    sealed class Rig
    {
        public FakeClock Clock = new FakeClock();
        public System.Collections.Generic.List<string> Log = new System.Collections.Generic.List<string>();
        public FakeStep[] Steps;
        public DungeonLoader Loader;
        public System.Threading.CancellationTokenSource Cts = new System.Threading.CancellationTokenSource();
        public Rig(params string[] names)
        {
            Steps = new FakeStep[names.Length];
            for (int i = 0; i < names.Length; i++) Steps[i] = new FakeStep { Name = names[i], Log = Log };
            Loader = new DungeonLoader(Steps, Clock, System.TimeSpan.FromSeconds(10));
        }
        public string Text() { lock (Log) return string.Join(", ", Log); }
    }

    static bool WaitUntil(System.Func<bool> cond)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (!cond()) { if (sw.ElapsedMilliseconds > 1000) return false; System.Threading.Thread.Sleep(1); }
        return true;
    }

    static string Started(Rig r, int i) { return WaitUntil(() => r.Steps[i].Loads == 1 && r.Steps[i].Tcs != null) ? null : "단계 " + r.Steps[i].Name + "가 시작되지 않음. 기록: [" + r.Text() + "]"; }

    static string Outcome(System.Threading.Tasks.Task run, string expect, System.Exception same)
    {
        if (!WaitUntil(() => run.IsCompleted)) return "RunAsync가 끝나지 않음 (기대: " + expect + ")";
        string got = run.Status == System.Threading.Tasks.TaskStatus.RanToCompletion ? "완료"
            : run.IsCanceled ? "취소"
            : run.Exception.InnerExceptions.Count == 1 && run.Exception.InnerException is System.TimeoutException ? "타임아웃"
            : "실패(" + run.Exception.InnerException.GetType().Name + ")";
        if (expect == "실패" && got.StartsWith("실패(") && run.Exception.InnerExceptions.Count == 1 && ReferenceEquals(run.Exception.InnerException, same)) return null;
        if (expect == "실패") return "단계가 던진 예외 그 자체로 실패해야 함: 결과 " + got;
        return got == expect ? null : "결과 상태: 기대 " + expect + ", 결과 " + got;
    }

    static string Log(Rig r, string expected) { string got = r.Text(); return got == expected ? null : "load/unload 기록: 기대 [" + expected + "], 결과 [" + got + "]"; }
    static string Released(Rig r) { return r.Clock.PendingCount == 0 ? null : "RunAsync가 끝났는데 타임아웃 Delay가 아직 대기 중 (해제되지 않음)"; }
    static string UsedClock(Rig r) { return r.Clock.Requested.Contains(System.TimeSpan.FromSeconds(10)) ? null : "IDelayProvider.Delay(timeout)으로 타임아웃을 재지 않음"; }

    // Each case runs on its own background thread with a 3-second bound, so code that blocks the
    // calling thread (.Wait(), .Result, Task.WaitAny) fails that case instead of hanging the judge.
    static void Run(string id, System.Func<string> body)
    {
        string reason = null;
        var thread = new System.Threading.Thread(() =>
        {
            try { reason = body(); }
            catch (System.Exception e) { reason = "예외 발생: " + e.GetType().Name + " (" + e.Message + ")"; }
        });
        thread.IsBackground = true;
        thread.Start();
        if (!thread.Join(3000)) { System.Console.WriteLine("[FAIL] " + id + " :: 3초 안에 끝나지 않음: RunAsync나 단계 처리가 호출 스레드를 막았습니다(동기 대기 금지)"); return; }
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    public static void Main()
    {
        Run("steps-run-in-order", () =>
        {
            var r = new Rig("map", "monsters", "sound");
            var run = r.Loader.RunAsync(r.Cts.Token);
            string e = Started(r, 0) ?? UsedClock(r);
            if (e != null) return e;
            if (r.Steps[1].Loads != 0) return "앞 단계가 끝나기 전에 다음 단계가 시작됨";
            if (!r.Steps[0].Token.CanBeCanceled) return "단계에 취소할 수 있는 토큰을 넘기지 않음";
            r.Clock.Advance(2); r.Steps[0].Tcs.SetResult();
            e = Started(r, 1); if (e != null) return e;
            r.Clock.Advance(3); r.Steps[1].Tcs.SetResult();
            e = Started(r, 2); if (e != null) return e;
            if (run.IsCompleted) return "마지막 단계가 끝나기 전에 RunAsync가 끝남";
            r.Steps[2].Tcs.SetResult();
            return Outcome(run, "완료", null) ?? Log(r, "load map, load monsters, load sound") ?? Released(r);
        });

        Run("player-cancel-rolls-back", () =>
        {
            var r = new Rig("map", "monsters", "sound");
            var run = r.Loader.RunAsync(r.Cts.Token);
            string e = Started(r, 0); if (e != null) return e;
            r.Steps[0].Tcs.SetResult();
            e = Started(r, 1); if (e != null) return e;
            r.Cts.Cancel();
            e = Outcome(run, "취소", null); if (e != null) return e;
            if (!r.Steps[1].Token.IsCancellationRequested) return "실행 중인 단계의 토큰이 취소되지 않음";
            return Log(r, "load map, load monsters, unload map") ?? Released(r);
        });

        Run("timeout-rolls-back", () =>
        {
            var r = new Rig("map", "monsters", "sound");
            var run = r.Loader.RunAsync(r.Cts.Token);
            string e = Started(r, 0); if (e != null) return e;
            r.Clock.Advance(3); r.Steps[0].Tcs.SetResult();
            e = Started(r, 1); if (e != null) return e;
            r.Clock.Advance(6); r.Steps[1].Tcs.SetResult();
            e = Started(r, 2); if (e != null) return e;
            r.Clock.Advance(0.5);
            if (run.IsCompleted) return "전체 9.5초 시점(제한 10초)에 RunAsync가 이미 끝남";
            r.Clock.Advance(0.5);
            e = Outcome(run, "타임아웃", null); if (e != null) return "단계별이 아니라 전체 10초 제한이어야 함. " + e;
            if (!r.Steps[2].Token.IsCancellationRequested) return "타임아웃 뒤에도 실행 중인 단계의 토큰이 취소되지 않음";
            return Log(r, "load map, load monsters, load sound, unload monsters, unload map") ?? Released(r);
        });

        Run("step-failure-propagates", () =>
        {
            var r = new Rig("map", "monsters", "sound");
            var run = r.Loader.RunAsync(r.Cts.Token);
            string e = Started(r, 0); if (e != null) return e;
            r.Steps[0].Tcs.SetResult();
            e = Started(r, 1); if (e != null) return e;
            var boom = new System.IO.InvalidDataException("monsters.bin 손상");
            r.Steps[1].Tcs.SetException(boom);
            e = Outcome(run, "실패", boom) ?? Log(r, "load map, load monsters, unload map") ?? Released(r);
            if (e != null) return e;
            var r2 = new Rig("map", "monsters");
            var sync = new System.InvalidOperationException("동기 예외");
            r2.Steps[0].CompletesSync = true;
            r2.Steps[1].ThrowsSync = sync;
            var run2 = r2.Loader.RunAsync(r2.Cts.Token);
            e = Outcome(run2, "실패", sync);
            return e == null ? Log(r2, "load map, load monsters, unload map") ?? Released(r2) : "LoadAsync가 동기적으로 던진 경우: " + e;
        });

        Run("already-canceled-and-empty", () =>
        {
            var r = new Rig("map", "monsters");
            r.Cts.Cancel();
            var run = r.Loader.RunAsync(r.Cts.Token);
            string e = Outcome(run, "취소", null);
            if (e != null) return "이미 취소된 토큰: " + e;
            if (r.Text() != "") return "이미 취소된 토큰인데 단계가 시작됨: [" + r.Text() + "]";
            e = Released(r); if (e != null) return e;
            var empty = new Rig();
            e = Outcome(empty.Loader.RunAsync(empty.Cts.Token), "완료", null);
            if (e != null) return "단계 0개: " + e;
            var syncAll = new Rig("map", "monsters", "sound");
            foreach (var s in syncAll.Steps) s.CompletesSync = true;
            e = Outcome(syncAll.Loader.RunAsync(syncAll.Cts.Token), "완료", null);
            return e != null ? "모든 단계가 동기 완료: " + e : Released(empty) ?? Released(syncAll) ?? Log(syncAll, "load map, load monsters, load sound");
        });

        Run("ignoring-step-does-not-hang", () =>
        {
            var r = new Rig("map", "thirdparty-sdk", "sound");
            r.Steps[1].IgnoresToken = true;
            var run = r.Loader.RunAsync(r.Cts.Token);
            string e = Started(r, 0); if (e != null) return e;
            r.Steps[0].Tcs.SetResult();
            e = Started(r, 1); if (e != null) return e;
            r.Cts.Cancel();
            e = Outcome(run, "취소", null);
            if (e != null) return "토큰을 무시하는 단계가 실행 중일 때 취소: " + e;
            e = Log(r, "load map, load thirdparty-sdk, unload map") ?? Released(r); if (e != null) return e;
            r.Steps[1].Tcs.SetResult();
            if (!WaitUntil(() => r.Steps[1].Unloads == 1)) return "버려진 단계가 나중에 성공했는데 Unload되지 않음. 기록: [" + r.Text() + "]";
            var r2 = new Rig("map", "thirdparty-sdk");
            r2.Steps[1].IgnoresToken = true;
            var run2 = r2.Loader.RunAsync(r2.Cts.Token);
            e = Started(r2, 0); if (e != null) return e;
            r2.Steps[0].Tcs.SetResult();
            e = Started(r2, 1); if (e != null) return e;
            r2.Clock.Advance(10);
            e = Outcome(run2, "타임아웃", null);
            if (e != null) return "토큰을 무시하는 단계가 실행 중일 때 타임아웃: " + e;
            r2.Steps[1].Tcs.SetException(new System.Exception("늦은 실패"));
            System.Threading.Thread.Sleep(20);
            return Log(r2, "load map, load thirdparty-sdk, unload map") ?? Released(r2);
        });

        Run("random-vs-model", () =>
        {
            var rng = new System.Random(81122);
            for (int round = 0; round < 150; round++)
            {
                int n = rng.Next(0, 6);
                var names = new string[n];
                for (int i = 0; i < n; i++) names[i] = "s" + i;
                var r = new Rig(names);
                foreach (var s in r.Steps) { int k = rng.Next(100); s.IgnoresToken = k < 15; s.CompletesSync = k >= 15 && k < 30; }
                var expected = new System.Collections.Generic.List<string>();
                var loaded = new System.Collections.Generic.List<FakeStep>();
                int idx = 0; double t = 0; string outcome = null; System.Exception failure = null; FakeStep abandoned = null;
                var run = r.Loader.RunAsync(r.Cts.Token);
                System.Action startNext = () =>
                {
                    while (idx < n) { expected.Add("load " + r.Steps[idx].Name); if (!r.Steps[idx].CompletesSync) return; loaded.Add(r.Steps[idx]); idx++; }
                    outcome = "완료";
                };
                System.Action rollback = () => { for (int i = loaded.Count - 1; i >= 0; i--) expected.Add("unload " + loaded[i].Name); };
                startNext();
                for (int ev = 0; ev < 40 && outcome == null; ev++)
                {
                    var cur = r.Steps[idx];
                    if (!WaitUntil(() => cur.Tcs != null)) return "라운드 " + round + ": 단계 " + cur.Name + "가 시작되지 않음";
                    int k = rng.Next(100);
                    if (k < 45) { cur.Tcs.SetResult(); loaded.Add(cur); idx++; startNext(); }
                    else if (k < 55) { failure = new System.InvalidOperationException("fail " + cur.Name); cur.Tcs.SetException(failure); outcome = "실패"; rollback(); }
                    else if (k < 92)
                    {
                        int dt = rng.Next(1, 5); t += dt; r.Clock.Advance(dt);
                        if (t >= 10) { outcome = "타임아웃"; if (cur.IgnoresToken) abandoned = cur; rollback(); }
                    }
                    else { r.Cts.Cancel(); outcome = "취소"; if (cur.IgnoresToken) abandoned = cur; rollback(); }
                }
                if (outcome == null) { r.Cts.Cancel(); outcome = "취소"; if (r.Steps[idx].IgnoresToken) abandoned = r.Steps[idx]; rollback(); }
                string e = Outcome(run, outcome, failure);
                if (e == null && abandoned != null)
                {
                    if (rng.Next(2) == 0) { abandoned.Tcs.SetResult(); expected.Add("unload " + abandoned.Name); WaitUntil(() => abandoned.Unloads == 1); }
                    else abandoned.Tcs.SetException(new System.Exception("late"));
                }
                if (e == null) e = Log(r, string.Join(", ", expected)) ?? Released(r);
                if (e != null) return "라운드 " + round + " (단계 " + n + "개): " + e;
            }
            return null;
        });
    }
}

