                        if (w.TryGetValue(P(x + 5000 * (round + 1), y), out int wv)) sum += wv;
                        if (k == P(x, y) && !(k != P(x, y)) && k.Equals(P(x, y))) sum += k.GetHashCode() & 1;
                    }
                _sink += sum;
                if (round > 0) bytes += System.GC.GetAllocatedBytesForCurrentThread() - before;
            }
