using System;
using System.Collections.Generic;
using System.Linq;

public sealed class Enemy
{
    public readonly int Id;
    public readonly int Wave;   // 1-based wave number
    public readonly int X, Y;   // tile position
    public int Hp;

    public Enemy(int id, int wave, int x, int y, int hp)
    {
        Id = id; Wave = wave; X = x; Y = y; Hp = hp;
    }
}

/// <summary>Plain C# combat state of one defence stage (no engine types).</summary>
public sealed class Battlefield
{
    public const int MaxChainTargets = 3;
    public const int ChainRange = 5;   // in tiles, measured as Euclidean distance

    private readonly List<Enemy> _enemies = new List<Enemy>();

    // One live view per wave: always reflects the current list, including enemies spawned later.
    private readonly IEnumerable<Enemy>[] _aliveByWave;

    public Battlefield(int waveCount)
    {
        if (waveCount < 1) throw new ArgumentOutOfRangeException(nameof(waveCount));
        _aliveByWave = new IEnumerable<Enemy>[waveCount];
        for (int wave = 1; wave <= waveCount; wave++)
        {
            _aliveByWave[wave - 1] = _enemies.Where(e => e.Wave == wave && e.Hp > 0);
        }
    }

    /// <summary>Number of enemies in the list, dead ones included until RemoveDead runs.</summary>
    public int Count => _enemies.Count;

    public void Spawn(Enemy enemy) => _enemies.Add(enemy);

    /// <summary>Alive enemies (Hp &gt; 0) of the given wave (1..waveCount), counted right now.</summary>
    public int AliveInWave(int wave) => _aliveByWave[wave - 1].Count();

    /// <summary>
    /// Hits up to MaxChainTargets alive enemies whose distance from (x, y) is at most ChainRange,
    /// nearest first (equal distance: earlier spawn first). Each of them loses `damage` Hp once.
    /// Returns the ids of the enemies that were hit, in hit order.
    /// </summary>
    public List<int> CastChainLightning(int x, int y, int damage)
    {
        IEnumerable<Enemy> targets = _enemies
            .Where(e => e.Hp > 0 && DistSq(e, x, y) <= ChainRange * ChainRange)
            .OrderBy(e => DistSq(e, x, y))
            .Take(MaxChainTargets);

        foreach (Enemy target in targets)
        {
            target.Hp -= damage;
        }

        return targets.Select(t => t.Id).ToList();
    }

    /// <summary>Removes every enemy with Hp &lt;= 0, keeping the order of the others. Returns how many were removed.</summary>
    public int RemoveDead()
    {
        int removed = 0;
        foreach (Enemy dead in _enemies.Where(e => e.Hp <= 0))
        {
            _enemies.Remove(dead);
            removed++;
        }
        return removed;
    }

    private static int DistSq(Enemy e, int x, int y)
    {
        int dx = e.X - x, dy = e.Y - y;
        return dx * dx + dy * dy;
    }
}

