using System;

/// <summary>One hit the player took. A small struct with no reference fields.</summary>
public readonly struct DamageEntry
{
    public readonly int Frame;     // simulation frame of the hit
    public readonly int SourceId;  // attacker id
    public readonly int Amount;    // damage dealt

    public DamageEntry(int frame, int sourceId, int amount)
    {
        Frame = frame; SourceId = sourceId; Amount = amount;
    }
}

/// <summary>
/// Fixed-capacity log of the most recent hits. When the log is full, Add overwrites the oldest entry.
/// Add, GetFromNewest and GetRecent must not allocate on the managed heap.
/// </summary>
public sealed class DamageLog
{
    private readonly DamageEntry[] _buffer; // the only allocation, made in the constructor
    private int _next;                      // slot the next Add writes to
    private int _count;                     // stored entries, at most _buffer.Length

    /// <summary>capacity must be at least 1, otherwise ArgumentOutOfRangeException.</summary>
    public DamageLog(int capacity)
    {
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));
        _buffer = new DamageEntry[capacity];
    }

    /// <summary>Maximum number of entries kept.</summary>
    public int Capacity => _buffer.Length;

    /// <summary>Number of entries currently stored: min(entries added since the last Clear, Capacity).</summary>
    public int Count => _count;

    /// <summary>Appends an entry in O(1). When Count == Capacity the oldest entry is overwritten.</summary>
    public void Add(DamageEntry entry)
    {
        _buffer[_next] = entry;            // when full, _next is exactly the oldest slot
        _next++;
        if (_next == _buffer.Length) _next = 0;
        if (_count < _buffer.Length) _count++;
    }

    /// <summary>Forgets every entry (Count becomes 0). Capacity is unchanged.</summary>
    public void Clear()
    {
        // DamageEntry holds no references, so the old values keep nothing alive and need no wiping.
        _next = 0;
        _count = 0;
    }

    /// <summary>
    /// The entry `ago` steps back from the newest: 0 is the newest, Count - 1 the oldest.
    /// Throws ArgumentOutOfRangeException when ago is outside [0, Count).
    /// </summary>
    public DamageEntry GetFromNewest(int ago)
    {
        if ((uint)ago >= (uint)_count) throw new ArgumentOutOfRangeException(nameof(ago));
        int index = _next - 1 - ago;
        if (index < 0) index += _buffer.Length;
        return _buffer[index];
    }

    /// <summary>
    /// The last min(n, Count) entries in chronological order (oldest first), returned as two read-only
    /// views into the internal buffer: all of `first`, then all of `second`. No copying.
    /// - When those entries are contiguous in the buffer, they are all in `first` and `second` is empty.
    /// - n == 0 (or an empty log): both are empty.
    /// - n &lt; 0: ArgumentOutOfRangeException.
    /// The views are valid until the next Add or Clear.
    /// </summary>
    public void GetRecent(int n, out ReadOnlySpan<DamageEntry> first, out ReadOnlySpan<DamageEntry> second)
    {
        if (n < 0) throw new ArgumentOutOfRangeException(nameof(n));
        if (n > _count) n = _count;

        // The newest n entries end just before _next. They start at _next - n, which may wrap.
        int start = _next - n;
        if (start >= 0)
        {
            first = new ReadOnlySpan<DamageEntry>(_buffer, start, n);
            second = ReadOnlySpan<DamageEntry>.Empty;
        }
        else
        {
            start += _buffer.Length;
            first = new ReadOnlySpan<DamageEntry>(_buffer, start, _buffer.Length - start); // tail of the array
            second = new ReadOnlySpan<DamageEntry>(_buffer, 0, _next);                     // head of the array
        }
    }
}

