// ===== hidden judge =====
public static class __Judge
{
    // Each case runs on its own thread with a 2-second limit.
    private static void Run(string id, System.Func<string> body)
    {
        string[] box = new string[1];
        var worker = new System.Threading.Thread(() =>
        {
            try { box[0] = body(); }
            catch (System.Exception e) { box[0] = "예외 발생: " + e.GetType().Name; }
        });
        worker.IsBackground = true;
        worker.Start();
        string reason = worker.Join(2000) ? box[0] : "2초 안에 끝나지 않음(무한 루프 의심)";
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    // Entry k carries Frame k, SourceId 100 + k, Amount 10 * k.
    private static DamageEntry E(int k) { return new DamageEntry(k, 100 + k, 10 * k); }

    private static string Fmt(System.ReadOnlySpan<DamageEntry> s)
    {
        var sb = new System.Text.StringBuilder("[");
        for (int i = 0; i < s.Length; i++)
        {
            if (i > 0) sb.Append(',');
            var e = s[i];
            sb.Append(e.Frame);
            if (e.SourceId != 100 + e.Frame || e.Amount != 10 * e.Frame) sb.Append("(손상)");
        }
        return sb.Append(']').ToString();
    }

    private static string Recent(DamageLog log, int n, string expectFirst, string expectSecond)
    {
        log.GetRecent(n, out var first, out var second);
        string f = Fmt(first), s = Fmt(second);
        return f == expectFirst && s == expectSecond ? null
            : "GetRecent(" + n + ") 기대 first=" + expectFirst + " second=" + expectSecond + ", 결과 first=" + f + " second=" + s;
    }

    private static string Throws<TEx>(System.Action a, string what) where TEx : System.Exception
    {
        try { a(); }
        catch (TEx) { return null; }
        catch (System.Exception e) { return what + ": " + typeof(TEx).Name + " 대신 " + e.GetType().Name; }
        return what + ": " + typeof(TEx).Name + "이 발생하지 않음";
    }

    public static void Main()
    {
        Run("before-wrap", () =>
        {
            var log = new DamageLog(5);
            for (int k = 1; k <= 3; k++) log.Add(E(k));
            if (log.Count != 3 || log.Capacity != 5) return "3개 추가 후 Count/Capacity 기대 3/5, 결과 " + log.Count + "/" + log.Capacity;
            return Recent(log, 2, "[2,3]", "[]") ?? Recent(log, 10, "[1,2,3]", "[]") ?? Recent(log, 0, "[]", "[]");
        });
        Run("wrap-two-segments", () =>
        {
            var log = new DamageLog(5);
            for (int k = 1; k <= 7; k++) log.Add(E(k));
            if (log.Count != 5) return "용량 5에 7개 추가 후 Count 기대 5, 결과 " + log.Count;
            return Recent(log, 5, "[3,4,5]", "[6,7]") ?? Recent(log, 3, "[5]", "[6,7]") ?? Recent(log, 2, "[6,7]", "[]") ?? Recent(log, 99, "[3,4,5]", "[6,7]");
        });
        Run("exact-lap-boundaries", () =>
        {
            var log = new DamageLog(4);
            for (int k = 1; k <= 4; k++) log.Add(E(k));
            string err = Recent(log, 4, "[1,2,3,4]", "[]");
            if (err != null) return "정확히 가득 찬 직후: " + err;
            for (int k = 5; k <= 8; k++) log.Add(E(k));
            err = Recent(log, 4, "[5,6,7,8]", "[]");
            if (err != null) return "정확히 두 바퀴 돈 직후: " + err;
            log.Add(E(9));
            return Recent(log, 4, "[6,7,8]", "[9]") ?? Recent(log, 1, "[9]", "[]");
        });
        Run("newest-first-access", () =>
        {
            var log = new DamageLog(3);
            for (int k = 1; k <= 5; k++) log.Add(E(k));
            for (int ago = 0; ago < 3; ago++)
            {
                var e = log.GetFromNewest(ago);
                if (e.Frame != 5 - ago || e.Amount != 10 * (5 - ago)) return "GetFromNewest(" + ago + ") 기대 프레임 " + (5 - ago) + ", 결과 " + e.Frame;
            }
            return Throws<System.ArgumentOutOfRangeException>(() => log.GetFromNewest(3), "GetFromNewest(Count)")
                ?? Throws<System.ArgumentOutOfRangeException>(() => log.GetFromNewest(-1), "GetFromNewest(-1)");
        });
        Run("invalid-args-and-clear", () =>
        {
            string err = Throws<System.ArgumentOutOfRangeException>(() => new DamageLog(0), "용량 0")
                ?? Throws<System.ArgumentOutOfRangeException>(() => new DamageLog(-3), "용량 -3");
            if (err != null) return err;
            var log = new DamageLog(4);
            for (int k = 1; k <= 6; k++) log.Add(E(k));
            err = Throws<System.ArgumentOutOfRangeException>(() => { log.GetRecent(-1, out var a, out var b); }, "GetRecent(-1)");
            if (err != null) return err;
            log.Clear();
            if (log.Count != 0 || log.Capacity != 4) return "Clear 후 Count/Capacity 기대 0/4, 결과 " + log.Count + "/" + log.Capacity;
            err = Recent(log, 3, "[]", "[]") ?? Throws<System.ArgumentOutOfRangeException>(() => log.GetFromNewest(0), "Clear 후 GetFromNewest(0)");
            if (err != null) return "Clear 후: " + err;
            log.Add(E(7)); log.Add(E(8));
            return Recent(log, 4, "[7,8]", "[]");
        });
        Run("capacity-one", () =>
        {
            var log = new DamageLog(1);
            for (int k = 1; k <= 3; k++) log.Add(E(k));
            if (log.Count != 1 || log.GetFromNewest(0).Frame != 3) return "용량 1: Count 기대 1, 최신 프레임 기대 3";
            return Recent(log, 1, "[3]", "[]") ?? Recent(log, 5, "[3]", "[]");
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(4096);
            const int Cap = 7;
            var log = new DamageLog(Cap);
            var all = new System.Collections.Generic.List<DamageEntry>();
            int frame = 0;
            for (int step = 0; step < 4000; step++)
            {
                int op = rng.Next(100);
                if (op < 60) { var e = E(++frame); log.Add(e); all.Add(e); }
                else if (op < 62) { log.Clear(); all.Clear(); }
                else
                {
                    int n = rng.Next(Cap + 3);
                    int take = System.Math.Min(n, System.Math.Min(all.Count, Cap));
                    var exp = new System.Text.StringBuilder("[");
                    for (int i = all.Count - take; i < all.Count; i++) { if (i > all.Count - take) exp.Append(','); exp.Append(all[i].Frame); }
                    exp.Append(']');
                    log.GetRecent(n, out var first, out var second);
                    string got = Fmt(first).TrimEnd(']') + (first.Length > 0 && second.Length > 0 ? "," : "") + Fmt(second).TrimStart('[');
                    if (got != exp.ToString()) return "step " + step + " GetRecent(" + n + ") 이어 붙인 결과 기대 " + exp + ", 결과 " + got;
                    if (second.Length > 0 && first.Length == 0) return "step " + step + " first가 비었는데 second에 항목이 있음";
                    if (take > 0)
                    {
                        int ago = rng.Next(take);
                        if (log.GetFromNewest(ago).Frame != all[all.Count - 1 - ago].Frame) return "step " + step + " GetFromNewest(" + ago + ") 불일치";
                    }
                }
                int expCount = System.Math.Min(all.Count, Cap);
                if (log.Count != expCount) return "step " + step + " Count 기대 " + expCount + ", 결과 " + log.Count;
            }
            return null;
        });
        Run("zero-alloc", () =>
        {
            var log = new DamageLog(256);
            long sum = 0;
            for (int round = 0; round < 2; round++)
            {
                long before = System.GC.GetAllocatedBytesForCurrentThread();
                for (int i = 0; i < 5000; i++)
                {
                    log.Add(new DamageEntry(i, i & 7, i % 50));
                    if ((i & 7) == 0)
                    {
                        log.GetRecent(64, out var first, out var second);
                        for (int j = 0; j < first.Length; j++) sum += first[j].Amount;
                        for (int j = 0; j < second.Length; j++) sum += second[j].Amount;
                        sum += log.GetFromNewest(log.Count - 1).Amount;
                    }
                }
                long allocated = System.GC.GetAllocatedBytesForCurrentThread() - before;
                // round 0 is warm-up; only the second round is judged
                if (round == 1 && allocated != 0) return "Add 5,000회 + GetRecent(64)·GetFromNewest 625회 구간에서 " + allocated + " B 할당됨 (기대 0 B)";
            }
            return sum > 0 ? null : "합계 계산이 비정상";
        });
    }
}

