using System;
using System.Buffers;

/// <summary>
/// Shortest paths on a 4-connected tile grid for RTS unit orders.
/// Every FindPath call rents its scratch buffers from the injected pool and gives each of them back
/// exactly once before the call ends, whether it returns normally or throws. Not thread-safe.
/// </summary>
public sealed class GridPathfinder
{
    private readonly ArrayPool<int> _pool;

    /// <summary>pool must not be null (ArgumentNullException).</summary>
    public GridPathfinder(ArrayPool<int> pool)
    {
        _pool = pool ?? throw new ArgumentNullException(nameof(pool));
    }

    /// <summary>
    /// walkable has width * height cells in row-major order (cell index = y * width + x).
    /// Writes one shortest path from start to goal, both included, into `path` and returns its length.
    /// - Returns 0 when goal cannot be reached, or when start or goal is not walkable.
    /// - start == goal (walkable): the path is just [start] and 1 is returned.
    /// - width or height &lt; 1, or walkable.Length != width * height: ArgumentException.
    /// - start or goal is not a cell index: ArgumentOutOfRangeException.
    /// - the path does not fit in `path`: ArgumentException.
    /// After warm-up, a call allocates nothing on the managed heap: all scratch memory comes from the pool.
    /// </summary>
    public int FindPath(ReadOnlySpan<bool> walkable, int width, int height, int start, int goal, Span<int> path)
    {
        // Validate before renting: nothing to give back if we throw here.
        if (width < 1 || height < 1 || walkable.Length != (long)width * height)
            throw new ArgumentException("walkable must contain width * height cells.", nameof(walkable));
        int cellCount = walkable.Length;
        if ((uint)start >= (uint)cellCount) throw new ArgumentOutOfRangeException(nameof(start));
        if ((uint)goal >= (uint)cellCount) throw new ArgumentOutOfRangeException(nameof(goal));
        if (!walkable[start] || !walkable[goal]) return 0;

        int[] prevBuffer = null, queueBuffer = null;
        try
        {
            // Each Rent sits inside the try: if the second one throws, finally still returns the first.
            prevBuffer = _pool.Rent(cellCount);
            queueBuffer = _pool.Rent(cellCount);

            // Rent may hand back a longer array that still holds someone else's data.
            // Use exactly cellCount elements, and initialise what is read before it is written.
            Span<int> prev = prevBuffer.AsSpan(0, cellCount);
            Span<int> queue = queueBuffer.AsSpan(0, cellCount);
            prev.Fill(-1);                 // queue needs no clearing: Bfs writes each slot before reading it

            Bfs(walkable, width, start, goal, prev, queue);
            if (prev[goal] == -1) return 0;

            // Everything we need from the buffers is copied out here, before they go back to the pool.
            int length = 1;
            for (int c = goal; c != start; c = prev[c]) length++;
            if (length > path.Length)
                throw new ArgumentException("path is too short for the result.", nameof(path));

            int i = length - 1;
            for (int c = goal; ; c = prev[c])
            {
                path[i--] = c;
                if (c == start) break;
            }
            return length;
        }
        finally
        {
            // Exactly once each, and never touched again. int holds no references and the data is not
            // secret, so clearArray: false is enough; the next renter initialises what it reads anyway.
            if (queueBuffer != null) _pool.Return(queueBuffer);
            if (prevBuffer != null) _pool.Return(prevBuffer);
        }
    }

    // ---- Provided: do not change. ----

    /// <summary>
    /// Breadth-first search from start. Preconditions: prev and queue have exactly walkable.Length elements,
    /// and every element of prev is -1 (queue may contain anything).
    /// Afterwards prev[start] == start, prev[c] is the previous cell on a shortest path from start to c,
    /// and prev[c] == -1 for every cell that was not reached. Stops as soon as goal is taken from the queue.
    /// </summary>
    private static void Bfs(ReadOnlySpan<bool> walkable, int width, int start, int goal, Span<int> prev, Span<int> queue)
    {
        if (prev.Length != walkable.Length || queue.Length != walkable.Length)
            throw new ArgumentException("Scratch spans must contain exactly one element per cell.");

        int head = 0, tail = 0;
        prev[start] = start;
        queue[tail++] = start;
        while (head < tail)
        {
            int cell = queue[head++];
            if (cell == goal) return;
            int x = cell % width;
            if (x > 0) Visit(walkable, prev, queue, ref tail, cell, cell - 1);
            if (x < width - 1) Visit(walkable, prev, queue, ref tail, cell, cell + 1);
            if (cell >= width) Visit(walkable, prev, queue, ref tail, cell, cell - width);
            if (cell + width < walkable.Length) Visit(walkable, prev, queue, ref tail, cell, cell + width);
        }
    }

    private static void Visit(ReadOnlySpan<bool> walkable, Span<int> prev, Span<int> queue, ref int tail, int from, int to)
    {
        if (!walkable[to] || prev[to] != -1) return;
        prev[to] = from;
        queue[tail++] = to;
    }
}

