// ===== hidden judge =====
// A strict pool: hands out LONGER arrays filled with leftover junk (both allowed by the ArrayPool<T>.Rent contract),
// records every rent/return by reference, and right after a Return overwrites the array, as another system that
// rents it next would. It can also be told to fail on the n-th Rent.
public sealed class __StrictPool : System.Buffers.ArrayPool<int>
{
    [System.ThreadStatic] public static __StrictPool Current;   // the strict pool of the case running on this thread
    public int Extra = 13, Rents, FailOnRent = -1;
    public readonly System.Collections.Generic.List<int[]> Out = new System.Collections.Generic.List<int[]>();
    public readonly System.Collections.Generic.List<int[]> Back = new System.Collections.Generic.List<int[]>();
    public string Violation;
    private bool _allBack;   // every array rented in this call is back and nothing was rented since
    private int _backMark;   // Back.Count when the current call began
    public __StrictPool() { Current = this; }
    public void BeginCall() { _allBack = false; _backMark = Back.Count; }
    // First-chance exception hook: an index taken from a returned (scribbled) array means a read after Return.
    public void OnException(System.Exception e)
    {
        if (_allBack && e is System.IndexOutOfRangeException)
            Violation = Violation ?? "반납한 배열을 반납 뒤에 읽음(반납 직후 int.MinValue로 덮어쓴 값을 인덱스로 써서 IndexOutOfRangeException)";
    }
    public override int[] Rent(int minimumLength)
    {
        Rents++;
        _allBack = false;
        if (Rents == FailOnRent) throw new System.OutOfMemoryException("simulated");
        var a = new int[minimumLength + Extra];
        for (int i = 0; i < a.Length; i++) a[i] = -2 - (i % 5);   // stale data from a previous renter (never -1)
        Out.Add(a);
        return a;
    }
    public override void Return(int[] array, bool clearArray = false)
    {
        int i = Out.FindIndex(x => ReferenceEquals(x, array));
        if (i < 0) { Violation = Violation ?? (Back.Exists(x => ReferenceEquals(x, array)) ? "같은 배열을 두 번 반납함" : "이 풀에서 빌리지 않은 배열을 반납함"); return; }
        Out.RemoveAt(i); Back.Add(array);
        if (Out.Count == 0) _allBack = true;
        System.Array.Fill(array, int.MinValue);   // the next renter scribbles over it
    }
    public string Check()
    {
        if (Violation != null) return Violation;
        if (Out.Count != 0) return "반납하지 않은 배열 " + Out.Count + "개가 남음";
        for (int k = _backMark; k < Back.Count; k++)
            foreach (int v in Back[k]) if (v != int.MinValue) return "반납한 배열에 반납 뒤에 값을 씀";
        return null;
    }
}

// Allocation-free pool for the steady-state measurement (fixed slots, reuse by reference).
public sealed class __StablePool : System.Buffers.ArrayPool<int>
{
    private readonly int[][] _slots = new int[8][];
    private readonly bool[] _inUse = new bool[8];
    public int Bad, Rents;
    public override int[] Rent(int minimumLength)
    {
        Rents++;
        for (int i = 0; i < 8; i++)
            if (_slots[i] != null && !_inUse[i] && _slots[i].Length >= minimumLength) { _inUse[i] = true; return _slots[i]; }
        for (int i = 0; i < 8; i++)
            if (_slots[i] == null) { _slots[i] = new int[minimumLength + 5]; _inUse[i] = true; return _slots[i]; }
        Bad++; return new int[minimumLength];
    }
    public override void Return(int[] array, bool clearArray = false)
    {
        for (int i = 0; i < 8; i++)
            if (ReferenceEquals(_slots[i], array)) { if (!_inUse[i]) Bad++; _inUse[i] = false; System.Array.Fill(array, int.MinValue); return; }
        Bad++;
    }
    public int InUse() { int n = 0; for (int i = 0; i < 8; i++) if (_inUse[i]) n++; return n; }
}

public static class __Judge
{
    private static void Run(string id, System.Func<string> body)
    {
        string[] box = new string[1];
        var worker = new System.Threading.Thread(() =>
        {
            try { box[0] = body(); }
            catch (System.Exception e)
            {
                var sp = __StrictPool.Current;
                box[0] = sp != null && sp.Violation != null ? sp.Violation : "예외 발생: " + e.GetType().Name;
            }
        }, 16 * 1024 * 1024);
        worker.IsBackground = true;
        worker.Start();
        string reason = worker.Join(2500) ? box[0] : "2.5초 안에 끝나지 않음(무한 루프 의심)";
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    private static bool[] Grid(params string[] rows)
    {
        var g = new bool[rows.Length * rows[0].Length];
        for (int y = 0; y < rows.Length; y++) for (int x = 0; x < rows[0].Length; x++) g[y * rows[0].Length + x] = rows[y][x] == '.';
        return g;
    }

    // Reference BFS distance in steps (-1 if unreachable).
    private static int RefSteps(bool[] g, int w, int s, int t)
    {
        if (!g[s] || !g[t]) return -1;
        var d = new int[g.Length]; System.Array.Fill(d, -1); d[s] = 0;
        var q = new System.Collections.Generic.Queue<int>(); q.Enqueue(s);
        while (q.Count > 0)
        {
            int c = q.Dequeue(); if (c == t) return d[c];
            int x = c % w;
            foreach (int n in new[] { x > 0 ? c - 1 : -1, x < w - 1 ? c + 1 : -1, c - w, c + w })
                if (n >= 0 && n < g.Length && g[n] && d[n] < 0) { d[n] = d[c] + 1; q.Enqueue(n); }
        }
        return -1;
    }

    // Checks a returned path; null when it is a valid shortest path.
    private static string CheckPath(bool[] g, int w, int s, int t, int len, int[] path)
    {
        int steps = RefSteps(g, w, s, t);
        if (steps < 0) return len == 0 ? null : "도달할 수 없는데 길이 " + len + "을 반환함";
        if (len != steps + 1) return "최단 경로 길이 기대 " + (steps + 1) + ", 결과 " + len;
        if (path[0] != s || path[len - 1] != t) return "경로의 시작/끝이 start/goal이 아님: " + path[0] + ".." + path[len - 1];
        for (int i = 0; i < len; i++)
        {
            int c = path[i];
            if (c < 0 || c >= g.Length || !g[c]) return "경로 " + i + "번째 칸 " + c + "이 걸을 수 없는 칸";
            if (i > 0) { int p = path[i - 1]; bool adj = (c == p + 1 && c % w != 0) || (c == p - 1 && p % w != 0) || c == p + w || c == p - w; if (!adj) return "경로의 " + p + "→" + c + "가 이웃 칸이 아님"; }
        }
        return null;
    }

    private static string Query(__StrictPool pool, bool[] g, int w, int s, int t)
    {
        var pf = new GridPathfinder(pool);
        var path = new int[g.Length];
        pool.BeginCall();
        int len = pf.FindPath(g, w, g.Length / w, s, t, path);
        return CheckPath(g, w, s, t, len, path) ?? pool.Check();
    }

    public static void Main()
    {
        System.AppDomain.CurrentDomain.FirstChanceException += (s, e) => { var sp = __StrictPool.Current; if (sp != null) sp.OnException(e.Exception); };
        string[] maze = {
            "..#.....",
            ".##.###.",
            "....#...",
            "#.#.#.#.",
            "..#...#.",
            ".####.#.",
            "........" };
        Run("small-cases", () =>
        {
            var pool = new __StrictPool();
            var line = Grid(".....");
            string err = Query(pool, line, 5, 0, 4) ?? Query(pool, line, 5, 3, 3) ?? Query(pool, line, 5, 4, 0);
            if (err != null) return "1×5 통로: " + err;
            var walled = Grid("..#..");
            err = Query(pool, walled, 5, 0, 4) ?? Query(pool, walled, 5, 2, 4) ?? Query(pool, walled, 5, 0, 2);
            if (err != null) return "벽으로 막힌 통로/막힌 칸: " + err;
            return pool.Rents == 0 ? "주입한 풀에서 아무것도 빌리지 않음" : null;
        });
        Run("maze-dirty-oversized-buffers", () =>
        {
            var pool = new __StrictPool { Extra = 97 };
            var g = Grid(maze);
            int[][] pairs = { new[] { 0, 55 }, new[] { 7, 48 }, new[] { 16, 39 }, new[] { 0, 3 }, new[] { 40, 23 } };
            foreach (var p in pairs) { string err = Query(pool, g, 8, p[0], p[1]); if (err != null) return "미로 " + p[0] + "→" + p[1] + ": " + err; }
            return null;
        });
        Run("path-too-small-returns-buffers", () =>
        {
            var pool = new __StrictPool();
            var g = Grid(maze);
            var pf = new GridPathfinder(pool);
            pool.BeginCall();
            try { pf.FindPath(g, 8, 7, 0, 55, new int[3]); return "경로가 들어가지 않는 path에 ArgumentException이 발생하지 않음"; }
            catch (System.ArgumentException) { }
            if (pool.Rents == 0) return "주입한 풀에서 아무것도 빌리지 않음";
            string err = pool.Check();
            if (err != null) return "예외로 끝난 호출 뒤: " + err;
            return Query(pool, g, 8, 0, 55);
        });
        Run("rent-failure-returns-earlier-buffers", () =>
        {
            var pool = new __StrictPool { FailOnRent = 2 };
            var g = Grid(maze);
            var pf = new GridPathfinder(pool);
            var path = new int[g.Length];
            pool.BeginCall();
            try
            {
                int len = pf.FindPath(g, 8, 7, 0, 55, path);
                if (pool.Rents >= 2) return "두 번째 Rent가 OutOfMemoryException을 던졌는데 FindPath가 정상 반환함";
                return CheckPath(g, 8, 0, 55, len, path) ?? pool.Check();   // a single combined Rent is fine too
            }
            catch (System.OutOfMemoryException) { }
            return pool.Check() is string e ? "두 번째 Rent 실패 뒤: " + e : null;
        });
        Run("invalid-arguments", () =>
        {
            try { new GridPathfinder(null); return "pool이 null인데 ArgumentNullException이 발생하지 않음"; } catch (System.ArgumentNullException) { }
            var pool = new __StrictPool();
            var pf = new GridPathfinder(pool);
            var g = Grid(maze); var path = new int[g.Length];
            pool.BeginCall(); try { pf.FindPath(g, 8, 6, 0, 5, path); return "walkable.Length != width*height인데 ArgumentException이 발생하지 않음"; } catch (System.ArgumentException) { }
            pool.BeginCall(); try { pf.FindPath(g, 8, 7, -1, 5, path); return "start가 -1인데 ArgumentOutOfRangeException이 발생하지 않음"; } catch (System.ArgumentOutOfRangeException) { }
            pool.BeginCall(); try { pf.FindPath(g, 8, 7, 0, 56, path); return "goal이 칸 수와 같은데 ArgumentOutOfRangeException이 발생하지 않음"; } catch (System.ArgumentOutOfRangeException) { }
            return pool.Check();
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(8128);
            var pool = new __StrictPool();
            for (int q = 0; q < 300; q++)
            {
                int w = 1 + rng.Next(12), h = 1 + rng.Next(12);
                var g = new bool[w * h];
                for (int i = 0; i < g.Length; i++) g[i] = rng.Next(100) < 70;
                pool.Extra = rng.Next(40);
                string err = Query(pool, g, w, rng.Next(g.Length), rng.Next(g.Length));
                if (err != null) return "질의 " + q + " (" + w + "×" + h + "): " + err;
            }
            return null;
        });
        Run("shared-pool-large-map", () =>
        {
            const int W = 256;
            var g = new bool[W * W];
            for (int i = 0; i < g.Length; i++) g[i] = true;
            for (int y = 0; y < W - 1; y++) g[y * W + 128] = false;        // a long wall with one gap at the bottom row
            var pf = new GridPathfinder(System.Buffers.ArrayPool<int>.Shared);
            var path = new int[g.Length];
            for (int k = 0; k < 3; k++)
            {
                int len = pf.FindPath(g, W, W, 0, W - 1, path);
                string err = CheckPath(g, W, 0, W - 1, len, path);
                if (err != null) return "ArrayPool<int>.Shared, 256×256 맵 " + (k + 1) + "번째 호출: " + err;
            }
            return null;
        });
        Run("zero-alloc-steady-state", () =>
        {
            const int W = 64;
            var g = new bool[W * W];
            for (int i = 0; i < g.Length; i++) g[i] = (i % 7) != 3 || (i / W) % 5 == 0;
            var pool = new __StablePool();
            var pf = new GridPathfinder(pool);
            var path = new int[g.Length];
            int len = 0;
            for (int i = 0; i < 3; i++) len = pf.FindPath(g, W, W, 0, g.Length - 1, path);   // warm-up
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int i = 0; i < 50; i++) len = pf.FindPath(g, W, W, 0, g.Length - 1, path);
            long allocated = System.GC.GetAllocatedBytesForCurrentThread() - before;
            string err = len == 0 ? "도달 가능한 목표인데 0을 반환함" : CheckPath(g, W, 0, g.Length - 1, len, path);
            if (err != null) return err;
            if (pool.Bad != 0 || pool.InUse() != 0) return "풀 사용 규칙 위반(이중 반납·남의 배열 반납·미반납)";
            if (pool.Rents == 0) return "주입한 풀에서 아무것도 빌리지 않음";
            return allocated == 0 ? null : "워밍업 뒤 FindPath 50회 구간에서 " + allocated + " B 할당됨 (기대 0 B)";
        });
    }
}

