using System;
using System.Collections.Generic;

public sealed class LevelConfig
{
    public readonly string Name;
    public readonly float DamageMultiplier;   // how hard enemies hit in this level
    public readonly int GoldMultiplier;       // how much loot enemies drop in this level

    public LevelConfig(string name, float damageMultiplier, int goldMultiplier)
    {
        Name = name; DamageMultiplier = damageMultiplier; GoldMultiplier = goldMultiplier;
    }
}

public sealed class Enemy
{
    public readonly string Type;
    public readonly int BaseDamage;
    public bool Alive = true;

    public Enemy(string type, int baseDamage) { Type = type; BaseDamage = baseDamage; }
}

public sealed class LootTable
{
    public readonly string EnemyType;
    public readonly int Gold;

    public LootTable(string enemyType, int gold) { EnemyType = enemyType; Gold = gold; }
}

/// <summary>Enemies of one level that are still alive. Used for the "level cleared" check.</summary>
public sealed class EnemyRegistry
{
    private static readonly List<Enemy> s_alive = new List<Enemy>();

    public int AliveCount => s_alive.Count;
    public void Register(Enemy enemy) => s_alive.Add(enemy);
    public void Unregister(Enemy enemy) => s_alive.Remove(enemy);
}

/// <summary>Builds the loot table of an enemy type for one level. Building is expensive, so tables are cached.</summary>
public sealed class LootTableCache
{
    private static readonly Dictionary<string, LootTable> s_tables = new Dictionary<string, LootTable>();
    private readonly LevelConfig _config;

    public LootTableCache(LevelConfig config) { _config = config; }

    /// <summary>Number of tables this cache has built (each enemy type at most once per level).</summary>
    public int BuildCount { get; private set; }

    public LootTable Get(string enemyType)
    {
        if (!s_tables.TryGetValue(enemyType, out LootTable table))
        {
            table = new LootTable(enemyType, BaseGold(enemyType) * _config.GoldMultiplier);
            BuildCount++;
            s_tables.Add(enemyType, table);
        }
        return table;
    }

    /// <summary>Stand-in for the expensive designer-data lookup. Do not change.</summary>
    public static int BaseGold(string enemyType) => enemyType.Length * 2;
}

/// <summary>Scales enemy damage by the level's difficulty.</summary>
public sealed class DamageCalculator
{
    private static LevelConfig s_config;   // looked up once and shared by every calculator

    public DamageCalculator(LevelConfig config)
    {
        if (s_config == null) s_config = config;
    }

    public int DamageFrom(Enemy enemy) => (int)MathF.Round(enemy.BaseDamage * s_config.DamageMultiplier);
}

/// <summary>
/// Everything that lives for one loaded level. While the loading screen is up, the game creates the
/// next level's session before it disposes the current one, so two sessions can be alive at once.
/// </summary>
public sealed class LevelSession : IDisposable
{
    public LevelConfig Config { get; }
    public EnemyRegistry Enemies { get; }
    public LootTableCache Loot { get; }
    public DamageCalculator Damage { get; }

    public LevelSession(LevelConfig config)
    {
        Config = config;
        Enemies = new EnemyRegistry();
        Loot = new LootTableCache(config);
        Damage = new DamageCalculator(config);
    }

    public Enemy Spawn(string type, int baseDamage)
    {
        var enemy = new Enemy(type, baseDamage);
        Enemies.Register(enemy);
        return enemy;
    }

    /// <summary>Kills an alive enemy of this level and returns the gold it drops.</summary>
    public int Kill(Enemy enemy)
    {
        enemy.Alive = false;
        Enemies.Unregister(enemy);
        return Loot.Get(enemy.Type).Gold;
    }

    public bool Cleared => Enemies.AliveCount == 0;

    /// <summary>Called when the level is unloaded.</summary>
    public void Dispose()
    {
    }
}

