// ===== hidden judge =====
// All cases run in ONE process, one after another, like levels in one play session.
public static class __Judge
{
    private static void Run(string id, System.Func<string> body)
    {
        string[] box = new string[1];
        var worker = new System.Threading.Thread(() =>
        {
            try { box[0] = body(); }
            catch (System.Exception e) { box[0] = "예외 발생: " + e.GetType().Name; }
        });
        worker.IsBackground = true;
        worker.Start();
        string reason = worker.Join(2000) ? box[0] : "2초 안에 끝나지 않음(무한 루프 의심)";
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    private static int Dmg(int baseDamage, float mult) { return (int)System.MathF.Round(baseDamage * mult); }

    // Plays a level and unloads it; returns weak references to objects that must not outlive the level.
    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    private static System.WeakReference[] PlayAndUnload(string name)
    {
        var config = new LevelConfig(name, 1.25f, 4);
        var session = new LevelSession(config);
        var survivor = session.Spawn("wyvern", 40);              // still alive when the level is unloaded
        var victim = session.Spawn("kobold", 8);
        session.Damage.DamageFrom(survivor);
        session.Kill(victim);
        var table = session.Loot.Get("kobold");
        var refs = new[] { new System.WeakReference(config), new System.WeakReference(survivor), new System.WeakReference(table), new System.WeakReference(session) };
        session.Dispose();
        return refs;
    }

    public static void Main()
    {
        Run("one-level", () =>
        {
            var s = new LevelSession(new LevelConfig("forest", 1.5f, 1));
            var a = s.Spawn("goblin", 10); var b = s.Spawn("orc", 20); var c = s.Spawn("slime", 4);
            if (s.Enemies.AliveCount != 3) return "3마리 생성 후 AliveCount 기대 3, 결과 " + s.Enemies.AliveCount;
            if (s.Damage.DamageFrom(b) != 30) return "배율 1.5에서 기본 20의 피해 기대 30, 결과 " + s.Damage.DamageFrom(b);
            int gold = s.Kill(a) + s.Kill(b) + s.Kill(c);
            if (gold != 12 + 6 + 10) return "골드 합계 기대 28, 결과 " + gold;
            if (!s.Cleared) return "모두 처치했는데 Cleared가 false (AliveCount " + s.Enemies.AliveCount + ")";
            s.Dispose();
            return null;
        });
        Run("next-level-starts-empty", () =>
        {
            var first = new LevelSession(new LevelConfig("cave", 1f, 1));
            first.Spawn("goblin", 10); first.Spawn("goblin", 10); first.Kill(first.Spawn("bat", 2));
            first.Dispose();                                    // two goblins are still alive in the old level
            var next = new LevelSession(new LevelConfig("castle", 1f, 1));
            var x = next.Spawn("knight", 30); var y = next.Spawn("archer", 15);
            if (next.Enemies.AliveCount != 2) return "새 레벨에서 2마리 생성 후 AliveCount 기대 2, 결과 " + next.Enemies.AliveCount;
            next.Kill(x); next.Kill(y);
            return next.Cleared ? null : "새 레벨의 적을 모두 처치했는데 Cleared가 false (AliveCount " + next.Enemies.AliveCount + ")";
        });
        Run("loot-uses-current-level", () =>
        {
            var normal = new LevelSession(new LevelConfig("normal", 1f, 1));
            int g1 = normal.Kill(normal.Spawn("goblin", 10));
            normal.Dispose();
            var hard = new LevelSession(new LevelConfig("hard", 1f, 3));
            int g2 = hard.Kill(hard.Spawn("goblin", 10));
            int g3 = hard.Kill(hard.Spawn("goblin", 10));
            if (g1 != 12 || g2 != 36 || g3 != 36) return "고블린 골드 기대 보통 12 / 어려움 36·36, 결과 " + g1 + " / " + g2 + "·" + g3;
            return hard.Loot.BuildCount == 1 ? null : "한 레벨 안에서 같은 종류의 표는 한 번만 만들어야 함: BuildCount 기대 1, 결과 " + hard.Loot.BuildCount;
        });
        Run("damage-uses-current-level", () =>
        {
            var easy = new LevelSession(new LevelConfig("easy", 0.5f, 1));
            int d1 = easy.Damage.DamageFrom(easy.Spawn("orc", 20));
            easy.Dispose();
            var nightmare = new LevelSession(new LevelConfig("nightmare", 2f, 1));
            int d2 = nightmare.Damage.DamageFrom(nightmare.Spawn("orc", 20));
            return d1 == 10 && d2 == 40 ? null : "오크(기본 20) 피해 기대 배율 0.5 → 10, 배율 2 → 40, 결과 " + d1 + ", " + d2;
        });
        Run("preloaded-sessions-are-independent", () =>
        {
            var current = new LevelSession(new LevelConfig("current", 1f, 1));
            current.Spawn("orc", 20); current.Spawn("orc", 20);
            var preload = new LevelSession(new LevelConfig("preload", 2f, 5));   // created while current is still alive
            var p1 = preload.Spawn("orc", 20); preload.Spawn("bat", 2); preload.Spawn("bat", 2);
            if (current.Enemies.AliveCount != 2 || preload.Enemies.AliveCount != 3) return "동시에 살아 있는 두 레벨의 AliveCount 기대 2/3, 결과 " + current.Enemies.AliveCount + "/" + preload.Enemies.AliveCount;
            if (current.Damage.DamageFrom(p1) != 20 || preload.Damage.DamageFrom(p1) != 40) return "레벨별 피해 배율이 섞임: 기대 20/40, 결과 " + current.Damage.DamageFrom(p1) + "/" + preload.Damage.DamageFrom(p1);
            current.Dispose();                                  // the loading screen finishes
            if (preload.Enemies.AliveCount != 3) return "이전 레벨 Dispose 뒤 새 레벨 AliveCount 기대 3, 결과 " + preload.Enemies.AliveCount;
            int gold = preload.Kill(p1);
            return gold == 30 ? null : "새 레벨 오크 골드 기대 30, 결과 " + gold;
        });
        Run("old-level-is-collectible", () =>
        {
            var refs = PlayAndUnload("old");
            var next = new LevelSession(new LevelConfig("new", 1f, 1));
            next.Kill(next.Spawn("kobold", 8)); next.Spawn("wyvern", 40);
            System.GC.Collect(); System.GC.WaitForPendingFinalizers(); System.GC.Collect();
            string[] names = { "이전 레벨의 LevelConfig", "이전 레벨에서 살아 있던 적", "이전 레벨의 LootTable", "이전 LevelSession" };
            for (int i = 0; i < refs.Length; i++)
                if (refs[i].IsAlive) return names[i] + "이(가) 레벨을 내린 뒤에도 수거되지 않음(무언가가 아직 참조함)";
            return next.Enemies.AliveCount == 1 ? null : "새 레벨 AliveCount 기대 1, 결과 " + next.Enemies.AliveCount;
        });
        Run("random-levels-vs-model", () =>
        {
            var rng = new System.Random(31337);
            string[] types = { "goblin", "orc", "slime", "dragon", "bat" };
            float[] mults = { 0.5f, 1f, 1.25f, 1.5f, 2f };
            LevelSession prev = null;
            for (int level = 0; level < 20; level++)
            {
                float dm = mults[rng.Next(mults.Length)]; int gm = 1 + rng.Next(4);
                var s = new LevelSession(new LevelConfig("L" + level, dm, gm));
                if (prev != null && rng.Next(2) == 0) { prev.Dispose(); prev = null; }   // sometimes unload before, sometimes after
                var alive = new System.Collections.Generic.List<Enemy>();
                var built = new System.Collections.Generic.HashSet<string>();
                for (int step = 0; step < 40; step++)
                {
                    if (alive.Count == 0 || rng.Next(3) > 0)
                    {
                        var e = s.Spawn(types[rng.Next(types.Length)], 1 + rng.Next(50));
                        alive.Add(e);
                        if (s.Damage.DamageFrom(e) != Dmg(e.BaseDamage, dm)) return "레벨 " + level + " 피해 기대 " + Dmg(e.BaseDamage, dm) + ", 결과 " + s.Damage.DamageFrom(e);
                    }
                    else
                    {
                        var e = alive[rng.Next(alive.Count)]; alive.Remove(e); built.Add(e.Type);
                        int gold = s.Kill(e);
                        if (gold != LootTableCache.BaseGold(e.Type) * gm) return "레벨 " + level + " " + e.Type + " 골드 기대 " + LootTableCache.BaseGold(e.Type) * gm + ", 결과 " + gold;
                    }
                    if (s.Enemies.AliveCount != alive.Count) return "레벨 " + level + " AliveCount 기대 " + alive.Count + ", 결과 " + s.Enemies.AliveCount;
                }
                if (s.Loot.BuildCount != built.Count) return "레벨 " + level + " BuildCount 기대 " + built.Count + "(레벨마다 종류별 1회), 결과 " + s.Loot.BuildCount;
                if (prev != null) prev.Dispose();
                prev = s;
            }
            return null;
        });
    }
}

