using System;

// 탄환 하나: float 8개 + int 8개 = 64바이트짜리 struct.
// Life·위치가 매 프레임 바뀌므로 readonly struct로는 만들 수 없다. 대신 상태를 바꾸지 않는 멤버에 readonly를 붙인다.
public struct Bullet
{
    public float X, Y, Vx, Vy;
    public float Life, Radius, Spin, Age;
    public int Damage, OwnerId, ColorRgba, Flags;
    public int PatternId, Reserved0, Reserved1, Reserved2;

    // readonly 멤버: in 매개변수나 ref readonly 변수에서 불러도 방어적 복사가 생기지 않는다
    public readonly float SpeedSq() => Vx * Vx + Vy * Vy;
}

public sealed class BulletPool
{
    private Bullet[] _items;
    private int _count;

    public BulletPool(int capacity) { _items = new Bullet[capacity]; }

    public int Count => _count;

    public int Add(in Bullet bullet)
    {
        if (_count == _items.Length) Array.Resize(ref _items, _items.Length * 2);
        _items[_count] = bullet;
        return _count++;
    }

    // 배열 원소 자체의 별칭을 돌려준다. 배열은 필드에 있으므로 메서드가 끝나도 살아 있다(ref safe context = 호출자).
    // 주의: Add가 배열을 키우면(Array.Resize) 예전에 받은 ref는 옛 배열을 가리킨다. ref를 Add 너머로 들고 있지 말 것.
    public ref Bullet GetRef(int index)
    {
        if ((uint)index >= (uint)_count) throw new ArgumentOutOfRangeException(nameof(index));
        return ref _items[index];
    }

    // 읽기 전용 별칭: 복사 없이 읽되, 호출자가 고칠 수는 없다
    public ref readonly Bullet Peek(int index)
    {
        if ((uint)index >= (uint)_count) throw new ArgumentOutOfRangeException(nameof(index));
        return ref _items[index];
    }
}

public static class BulletSystem
{
    public static void Tick(BulletPool pool, float dt)
    {
        for (int i = 0; i < pool.Count; i++)
        {
            ref Bullet b = ref pool.GetRef(i);   // 'ref'를 빼고 var b = pool.GetRef(i)로 받으면 다시 복사본이 된다
            b.X += b.Vx * dt;
            b.Y += b.Vy * dt;
            b.Life -= dt;
            b.Age += dt;
        }
    }

    public static int TotalThreat(BulletPool pool, float minSpeedSq)
    {
        int sum = 0;
        for (int i = 0; i < pool.Count; i++) sum += ThreatOf(in pool.Peek(i), minSpeedSq);
        return sum;
    }

    // in: 64바이트를 복사하지 않고 읽기 전용 참조로 받는다. SpeedSq가 readonly 멤버라 방어적 복사도 없다.
    private static int ThreatOf(in Bullet b, float minSpeedSq)
    {
        return b.Life > 0f && b.SpeedSq() >= minSpeedSq ? b.Damage : 0;
    }
}

