using System;
using System.Collections.Generic;

// 몬스터 종류별 설정처럼 크고, 필요하면 다시 만들 수 있는 데이터를 키로 캐시한다.
// 누군가 쓰고 있는 동안에는 같은 인스턴스를 돌려주고, 아무도 쓰지 않으면 GC가 수거할 수 있어야 한다.
public sealed class ConfigCache<T> where T : class
{
    private readonly Func<string, T> _loader;
    private readonly Func<T, WeakReference<T>> _createWeak;
    // 캐시는 WeakReference만 들고 있다. T를 강하게 가리키는 필드나 컬렉션은 없다.
    private readonly Dictionary<string, WeakReference<T>> _entries = new Dictionary<string, WeakReference<T>>();
    // PurgeDead에서 지울 키를 모아 두는 재사용 버퍼(열거 중 Remove를 피한다).
    private readonly List<string> _deadKeys = new List<string>();

    public ConfigCache(Func<string, T> loader)
        : this(loader, target => new WeakReference<T>(target))
    {
    }

    public ConfigCache(Func<string, T> loader, Func<T, WeakReference<T>> createWeak)
    {
        _loader = loader ?? throw new ArgumentNullException(nameof(loader));
        _createWeak = createWeak ?? throw new ArgumentNullException(nameof(createWeak));
    }

    public T Get(string key)
    {
        if (key == null) throw new ArgumentNullException(nameof(key));

        // TryGetTarget은 한 번만 부르고 그 결과(강한 참조)를 그대로 반환한다.
        // "살아 있나 확인"과 "꺼내기"를 따로 하면 그 사이에 GC가 수거할 수 있다.
        if (_entries.TryGetValue(key, out WeakReference<T> weak) && weak.TryGetTarget(out T alive))
            return alive;

        T loaded = _loader(key);
        if (loaded == null) throw new InvalidOperationException("loader returned null for key '" + key + "'");

        if (weak != null)
            weak.SetTarget(loaded);              // 수거된 항목: 약한 참조 객체(와 그 GC 핸들)를 재사용
        else
            _entries.Add(key, _createWeak(loaded));   // 새 키: 이때 한 번만 만든다

        return loaded;                           // 지역 변수 loaded가 반환 순간까지 강한 참조다
    }

    public bool TryGetLoaded(string key, out T config)
    {
        if (key == null) throw new ArgumentNullException(nameof(key));
        if (_entries.TryGetValue(key, out WeakReference<T> weak) && weak.TryGetTarget(out config))
            return true;
        config = null;
        return false;
    }

    public int EntryCount => _entries.Count;

    public int PurgeDead()
    {
        _deadKeys.Clear();
        foreach (KeyValuePair<string, WeakReference<T>> pair in _entries)
        {
            if (!pair.Value.TryGetTarget(out _)) _deadKeys.Add(pair.Key);
        }
        for (int i = 0; i < _deadKeys.Count; i++) _entries.Remove(_deadKeys[i]);
        int removed = _deadKeys.Count;
        _deadKeys.Clear();
        return removed;
    }
}

