public sealed class __Cfg
{
    public readonly string Name; public readonly int Serial;
    public __Cfg(string name, int serial) { Name = name; Serial = serial; }
}

public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + " " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 로더 호출 횟수를 세는 가짜 로더와, 만들어진 약한 참조를 기록하는 팩터리
    sealed class Rig
    {
        public int Loads, Weaks;
        public readonly System.Collections.Generic.Dictionary<string, System.WeakReference<__Cfg>> Made = new System.Collections.Generic.Dictionary<string, System.WeakReference<__Cfg>>();
        public ConfigCache<__Cfg> Cache;
        public Rig(bool seam)
        {
            System.Func<string, __Cfg> loader = k => new __Cfg(k, ++Loads);
            if (!seam) { Cache = new ConfigCache<__Cfg>(loader); return; }
            Cache = new ConfigCache<__Cfg>(loader, c => { Weaks++; var w = new System.WeakReference<__Cfg>(c); Made[c.Name] = w; return w; });
        }
        // "GC가 이 설정을 수거했다"를 재현한다: 캐시가 가진 약한 참조의 대상을 지운다.
        public string Kill(string key)
        {
            if (!Made.TryGetValue(key, out var w)) return "키 \"" + key + "\"를 저장할 때 createWeak 팩터리를 호출하지 않았다(캐시가 약한 참조를 쓰지 않음)";
            w.SetTarget(null); return null;
        }
    }

    public static void Main()
    {
        Run("same-instance-while-held", () =>
        {
            var r = new Rig(false);
            var a = r.Cache.Get("goblin");
            System.GC.Collect(); System.GC.WaitForPendingFinalizers(); System.GC.Collect();
            var b = r.Cache.Get("goblin");
            if (!object.ReferenceEquals(a, b)) return "강한 참조(a)를 들고 있는 동안 Get(\"goblin\")이 다른 인스턴스를 반환";
            if (r.Loads != 1) return "같은 키 두 번 Get: loader 호출 기대 1 / 결과 " + r.Loads;
            var c = r.Cache.Get("orc");
            if (object.ReferenceEquals(a, c) || r.Loads != 2) return "다른 키 Get(\"orc\"): 새 인스턴스와 loader 2회를 기대 / loader " + r.Loads;
            System.GC.KeepAlive(a); System.GC.KeepAlive(c);
            return null;
        });

        Run("weak-factory-once-per-key", () =>
        {
            var r = new Rig(true);
            var a = r.Cache.Get("goblin");
            string e = r.Weaks == 1 ? null : "새 키 저장 시 createWeak 호출 기대 1 / 결과 " + r.Weaks;
            if (e != null) return e;
            if (!r.Made["goblin"].TryGetTarget(out var t) || !object.ReferenceEquals(t, a)) return "createWeak에 넘긴 대상이 Get이 반환한 설정과 다름";
            r.Cache.Get("goblin"); var o1 = r.Cache.Get("orc"); var o2 = r.Cache.Get("orc");
            if (r.Weaks != 2 || r.Loads != 2) return "goblin 2회·orc 2회 Get 후 createWeak 기대 2, loader 기대 2 / 결과 " + r.Weaks + ", " + r.Loads;
            if (r.Cache.EntryCount != 2) return "EntryCount 기대 2 / 결과 " + r.Cache.EntryCount;
            System.GC.KeepAlive(a); System.GC.KeepAlive(o1); System.GC.KeepAlive(o2); // 강한 참조를 끝까지 들고 있어 실제 GC가 결과를 바꾸지 못한다
            return null;
        });

        Run("reload-after-collected", () =>
        {
            var r = new Rig(true);
            var a = r.Cache.Get("goblin");
            string e = r.Kill("goblin"); if (e != null) return e;
            var b = r.Cache.Get("goblin");
            if (object.ReferenceEquals(a, b)) return "약한 참조가 비었는데 Get이 예전 인스턴스를 반환(캐시가 강한 참조를 따로 들고 있음)";
            if (r.Loads != 2) return "수거 뒤 Get: loader 호출 기대 2 / 결과 " + r.Loads;
            if (r.Weaks != 1) return "수거 뒤 다시 로드할 때 기존 WeakReference를 SetTarget으로 재사용해야 함: createWeak 호출 기대 1 / 결과 " + r.Weaks;
            if (!r.Made["goblin"].TryGetTarget(out var t) || !object.ReferenceEquals(t, b)) return "다시 로드한 설정이 기존 약한 참조에 들어 있지 않음";
            var c = r.Cache.Get("goblin");
            if (!object.ReferenceEquals(b, c) || r.Loads != 2) return "다시 로드한 뒤의 Get이 같은 인스턴스를 반환하지 않음";
            return r.Cache.EntryCount == 1 ? null : "EntryCount 기대 1 / 결과 " + r.Cache.EntryCount;
        });

        Run("try-get-loaded-never-loads", () =>
        {
            var r = new Rig(true);
            if (r.Cache.TryGetLoaded("goblin", out var none) || none != null) return "처음 보는 키에 TryGetLoaded가 true 또는 null 아닌 값";
            if (r.Loads != 0) return "TryGetLoaded가 loader를 호출함";
            var a = r.Cache.Get("goblin");
            if (!r.Cache.TryGetLoaded("goblin", out var got) || !object.ReferenceEquals(got, a)) return "살아 있는 설정에 TryGetLoaded가 false 또는 다른 인스턴스";
            string e = r.Kill("goblin"); if (e != null) return e;
            if (r.Cache.TryGetLoaded("goblin", out var dead)) return "수거된 설정에 TryGetLoaded가 true(캐시가 강한 참조를 들고 있음)";
            return r.Loads == 1 ? null : "TryGetLoaded가 loader를 호출함: loader 기대 1 / 결과 " + r.Loads;
        });

        Run("purge-dead-entries", () =>
        {
            var r = new Rig(true);
            var a = r.Cache.Get("a"); var b = r.Cache.Get("b"); var c = r.Cache.Get("c");
            if (r.Cache.PurgeDead() != 0) return "모두 살아 있는데 PurgeDead가 0이 아님";
            System.GC.KeepAlive(a); System.GC.KeepAlive(c); // 첫 PurgeDead까지는 a, c를 강하게 붙잡는다
            string e = r.Kill("a") ?? r.Kill("c"); if (e != null) return e;
            int removed = r.Cache.PurgeDead();
            if (removed != 2) return "a, c 수거 후 PurgeDead 반환 기대 2 / 결과 " + removed;
            if (r.Cache.EntryCount != 1) return "PurgeDead 후 EntryCount 기대 1 / 결과 " + r.Cache.EntryCount;
            if (!r.Cache.TryGetLoaded("b", out var bb) || !object.ReferenceEquals(bb, b)) return "살아 있는 b가 PurgeDead로 사라짐";
            var a2 = r.Cache.Get("a");
            if (r.Loads != 4 || r.Weaks != 4 || r.Cache.EntryCount != 2) return "지워진 키 a를 다시 Get: loader 4, createWeak 4, EntryCount 2 기대 / 결과 " + r.Loads + ", " + r.Weaks + ", " + r.Cache.EntryCount;
            int again = r.Cache.PurgeDead();
            System.GC.KeepAlive(a2); System.GC.KeepAlive(b); // 살아 있어야 할 설정은 끝까지 강하게 붙잡는다
            return again == 0 ? null : "두 번째 PurgeDead가 0이 아님: " + again;
        });

        Run("hit-path-zero-alloc", () =>
        {
            var r = new Rig(false);
            var a = r.Cache.Get("goblin");
            for (int i = 0; i < 100; i++) { r.Cache.Get("goblin"); r.Cache.TryGetLoaded("goblin", out _); }
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int i = 0; i < 10000; i++) { r.Cache.Get("goblin"); r.Cache.TryGetLoaded("goblin", out _); }
            long used = System.GC.GetAllocatedBytesForCurrentThread() - before;
            System.GC.KeepAlive(a);
            return used == 0 ? null : "캐시 적중 Get + TryGetLoaded 1만 회에 힙 할당 " + used + " B (0 B 기대)";
        });

        Run("null-key-and-null-load", () =>
        {
            var r = new Rig(true);
            try { r.Cache.Get(null); return "Get(null)이 예외 없이 반환"; } catch (System.ArgumentNullException) { }
            var bad = new ConfigCache<__Cfg>(k => null, c => new System.WeakReference<__Cfg>(c));
            try { bad.Get("ghost"); return "loader가 null을 반환했는데 예외가 없음"; } catch (System.InvalidOperationException) { }
            return bad.EntryCount == 0 ? null : "loader가 null을 반환한 키가 사전에 남음: EntryCount " + bad.EntryCount;
        });
    }
}

