using System;
using System.Collections.Generic;
using System.Globalization;

public sealed class Enemy
{
    public readonly int Id;
    public float X, Y;
    public Enemy(int id, float x, float y) { Id = id; X = x; Y = y; }
}

// HUD 위협 목록의 한 줄. 위협도 높은 순, 같으면 EnemyId 작은 순.
// [버그 3 수정] 제네릭 IComparable<ThreatEntry>로 비교한다. 비제네릭 CompareTo(object)는 인자를 박싱한다.
public struct ThreatEntry : IComparable<ThreatEntry>
{
    public int EnemyId;
    public int Threat;
    public ThreatEntry(int enemyId, int threat) { EnemyId = enemyId; Threat = threat; }

    public int CompareTo(ThreatEntry other)
    {
        if (Threat != other.Threat) return other.Threat.CompareTo(Threat);
        return EnemyId.CompareTo(other.EnemyId);
    }
}

// 전투 디버그 로그. 출시 빌드에서는 Enabled = false로 돈다.
public sealed class CombatLog
{
    public bool Enabled;
    public readonly List<string> Lines = new List<string>();

    public void Write(string message)
    {
        if (!Enabled) return;
        Lines.Add(message);
    }

    public void Write(string format, params object[] args)
    {
        if (!Enabled) return;
        Lines.Add(string.Format(CultureInfo.InvariantCulture, format, args));
    }
}

public static class SmallSort
{
    // [버그 3 수정] where T : IComparable<T>. 값 형식 T에서도 CompareTo(T)가 박싱 없이 불린다.
    public static void InsertionSort<T>(T[] items, int count) where T : IComparable<T>
    {
        for (int i = 1; i < count; i++)
        {
            T key = items[i];
            int j = i - 1;
            while (j >= 0 && items[j].CompareTo(key) > 0)
            {
                items[j + 1] = items[j];
                j--;
            }
            items[j + 1] = key;
        }
    }
}

// 매 프레임 호출되는 타기팅 시스템
public sealed class TargetingSystem
{
    private readonly CombatLog _log;
    // [버그 2 수정] 비교 델리게이트는 생성자에서 한 번만 만든다. 기준점은 필드로 넘긴다.
    private readonly Comparison<Enemy> _byDistance;
    private float _px, _py;

    public TargetingSystem(CombatLog log)
    {
        _log = log;
        _byDistance = CompareByDistance;
    }

    public void SortByDistance(List<Enemy> enemies, float px, float py)
    {
        // [버그 1 수정] 보간 문자열은 호출 전에 만들어지므로, 꺼져 있으면 아예 만들지 않는다.
        if (_log.Enabled) _log.Write($"[Target] sort {enemies.Count} enemies");
        if (enemies.Count < 2) return;
        _px = px;
        _py = py;
        enemies.Sort(_byDistance);   // List<T>.Sort(Comparison<T>)는 델리게이트를 그대로 쓴다
    }

    public void RankThreats(ThreatEntry[] entries, int count)
    {
        SmallSort.InsertionSort(entries, count);
        // [버그 1 수정] params object[] 배열과 int 박싱도 호출하는 쪽에서 생기므로 같은 방식으로 막는다.
        if (_log.Enabled) _log.Write("[Target] rank {0} threats, top {1}", count, count > 0 ? entries[0].Threat : -1);
    }

    private int CompareByDistance(Enemy a, Enemy b)
    {
        int c = DistSq(a, _px, _py).CompareTo(DistSq(b, _px, _py));
        return c != 0 ? c : a.Id.CompareTo(b.Id);
    }

    private static float DistSq(Enemy e, float px, float py)
    {
        float dx = e.X - px, dy = e.Y - py;
        return dx * dx + dy * dy;
    }
}

