    }

    static uint s_seed = 20261122u;
    static int Rnd(int n) { s_seed = s_seed * 1664525u + 1013904223u; return (int)((s_seed >> 8) % (uint)n); }

    static System.Collections.Generic.List<Enemy> MakeEnemies(int n)
    {
        var list = new System.Collections.Generic.List<Enemy>(n);
        for (int i = 0; i < n; i++) list.Add(new Enemy(100 + Rnd(1000), Rnd(9) - 4, Rnd(9) - 4)); // 좁은 격자: 거리 동률이 자주 나온다
        return list;
    }

    static string Ids(System.Collections.Generic.List<Enemy> list)
    {
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < list.Count; i++) { if (i > 0) sb.Append(','); sb.Append(list[i].Id); }
        return sb.ToString();
    }

    // 워밍업 뒤 action을 calls번 실행하는 동안의 이 스레드 힙 할당 바이트
    static long Measure(System.Action action, int calls)
    {
        for (int i = 0; i < 50; i++) action();
        long before = System.GC.GetAllocatedBytesForCurrentThread();
        for (int i = 0; i < calls; i++) action();
        return System.GC.GetAllocatedBytesForCurrentThread() - before;
    }

    public static void Main()
    {
        Run("sort-order-matches-reference", () =>
        {
            var sys = new TargetingSystem(new CombatLog());
            for (int run = 0; run < 300; run++)
            {
                var list = MakeEnemies(1 + Rnd(24));
                float px = Rnd(5) - 2, py = Rnd(5) - 2;
                var expected = new System.Collections.Generic.List<Enemy>(list);
                for (int i = 1; i < expected.Count; i++) // 기준: (거리², Id) 순 삽입 정렬
                {
                    var k = expected[i]; float dk = (k.X - px) * (k.X - px) + (k.Y - py) * (k.Y - py); int j = i - 1;
                    while (j >= 0) { var e = expected[j]; float de = (e.X - px) * (e.X - px) + (e.Y - py) * (e.Y - py); if (de < dk || (de == dk && e.Id <= k.Id)) break; expected[j + 1] = e; j--; }
                    expected[j + 1] = k;
                }
                string before = Ids(list);
                sys.SortByDistance(list, px, py);
                if (Ids(list) != Ids(expected)) return "입력 [" + before + "] 기준점 (" + px + "," + py + "): 기대 [" + Ids(expected) + "] / 결과 [" + Ids(list) + "]";
            }
            return null;
        });

        Run("rank-order-matches-reference", () =>
        {
            var sys = new TargetingSystem(new CombatLog());
            for (int run = 0; run < 300; run++)
            {
                int len = 1 + Rnd(20), count = Rnd(len + 1);
                var a = new ThreatEntry[len];
                for (int i = 0; i < len; i++) a[i] = new ThreatEntry(Rnd(30), Rnd(6) * 10);
                var exp = (ThreatEntry[])a.Clone();
                for (int i = 1; i < count; i++)
                {
                    var k = exp[i]; int j = i - 1;
                    while (j >= 0 && (exp[j].Threat < k.Threat || (exp[j].Threat == k.Threat && exp[j].EnemyId > k.EnemyId))) { exp[j + 1] = exp[j]; j--; }
                    exp[j + 1] = k;
                }
                sys.RankThreats(a, count);
                for (int i = 0; i < len; i++)
                    if (a[i].EnemyId != exp[i].EnemyId || a[i].Threat != exp[i].Threat)
                        return "len " + len + ", count " + count + ": " + i + "번 칸 기대 (id " + exp[i].EnemyId + ", 위협 " + exp[i].Threat + ") / 결과 (id " + a[i].EnemyId + ", 위협 " + a[i].Threat + ")";
            }
            return null;
        });

        Run("log-lines-when-enabled", () =>
        {
            var log = new CombatLog { Enabled = true };
            var sys = new TargetingSystem(log);
            sys.SortByDistance(new System.Collections.Generic.List<Enemy> { new Enemy(1, 3, 0), new Enemy(2, 1, 0), new Enemy(3, 2, 0) }, 0, 0);
            sys.SortByDistance(new System.Collections.Generic.List<Enemy> { new Enemy(9, 0, 0) }, 0, 0);
            sys.RankThreats(new[] { new ThreatEntry(4, 30), new ThreatEntry(5, 90), new ThreatEntry(6, 50), new ThreatEntry(7, 90) }, 4);
            sys.RankThreats(new ThreatEntry[0], 0);
            string[] expected = { "[Target] sort 3 enemies", "[Target] sort 1 enemies", "[Target] rank 4 threats, top 90", "[Target] rank 0 threats, top -1" };
            if (log.Lines.Count != expected.Length) return "켜진 로그 줄 수 기대 " + expected.Length + " / 결과 " + log.Lines.Count;
            for (int i = 0; i < expected.Length; i++) if (log.Lines[i] != expected[i]) return i + "번 줄 기대 \"" + expected[i] + "\" / 결과 \"" + log.Lines[i] + "\"";
            var off = new CombatLog();
            new TargetingSystem(off).RankThreats(new[] { new ThreatEntry(1, 1) }, 1);
            return off.Lines.Count == 0 ? null : "꺼진 로그에 줄이 기록됨";
        });

        Run("sort-zero-alloc-when-log-off", () =>
        {
            var sys = new TargetingSystem(new CombatLog());
            var list = MakeEnemies(16);
            int frame = 0;
            long used = Measure(() => { frame++; sys.SortByDistance(list, frame % 7 - 3, frame % 5 - 2); }, 1000);
            return used == 0 ? null : "로그가 꺼진 상태로 적 16명 SortByDistance 1,000회: 힙 할당 " + used + " B (호출당 " + used / 1000 + " B, 0 B 기대)";
        });

        Run("early-return-zero-alloc", () =>
        {
            var sys = new TargetingSystem(new CombatLog());
            var one = new System.Collections.Generic.List<Enemy> { new Enemy(1, 0, 0) };
            var none = new System.Collections.Generic.List<Enemy>();
            long used = Measure(() => { sys.SortByDistance(one, 1, 1); sys.SortByDistance(none, 1, 1); }, 1000);
            return used == 0 ? null : "정렬할 필요가 없는 0명·1명 목록(로그 꺼짐) 1,000쌍: 힙 할당 " + used + " B (쌍당 " + used / 1000 + " B, 0 B 기대)";
        });

        Run("rank-zero-alloc-when-log-off", () =>
        {
            var sys = new TargetingSystem(new CombatLog());
            var source = new ThreatEntry[24];
            for (int i = 0; i < source.Length; i++) source[i] = new ThreatEntry(i, (i * 37) % 11 * 10);
            var work = new ThreatEntry[24];
            long used = Measure(() => { System.Array.Copy(source, work, 24); sys.RankThreats(work, 24); }, 1000);
            return used == 0 ? null : "로그가 꺼진 상태로 24개 RankThreats 1,000회: 힙 할당 " + used + " B (호출당 " + used / 1000 + " B, 0 B 기대)";
        });

        Run("insertion-sort-other-types", () =>
        {
            var ints = new[] { 5, 3, 9, 1, 7, 0 };
            SmallSort.InsertionSort(ints, 4);
            if (string.Join(",", ints) != "1,3,5,9,7,0") return "int[] {5,3,9,1,7,0}을 count 4로 정렬: 기대 1,3,5,9,7,0 / 결과 " + string.Join(",", ints);
            var words = new[] { "orc", "bat", "imp" };
            SmallSort.InsertionSort(words, 3);
            return string.Join(",", words) == "bat,imp,orc" ? null : "string[] 정렬 결과 " + string.Join(",", words);
        });
    }
}

