problems.solutionCode:
using System;

// 예약한 타이머를 가리키는 값. default(TimerHandle)은 어떤 타이머도 가리키지 않는다(세대는 1부터 시작).
public readonly struct TimerHandle
{
    public readonly int Index;
    public readonly int Generation;
    public TimerHandle(int index, int generation) { Index = index; Generation = generation; }
}

// 해시 타이밍 휠(Varghese & Lauck의 Scheme 6): 슬롯 = 만기 틱 mod wheelSize, 슬롯마다 정렬하지 않은 이중 연결 리스트.
// 항목은 미리 잡아 둔 struct 배열에 있고, 리스트 연결은 배열 인덱스로 한다(침투형 연결 리스트). 실행 중 할당 없음.
public sealed class TimerWheel
{
    private const byte Free = 0, InSlot = 1, InDue = 2;

    private struct Entry
    {
        public long DueTick;
        public int CallbackId;
        public int Payload;
        public int Prev;        // 같은 리스트의 앞 항목(-1 = 없음)
        public int Next;        // 같은 리스트의 뒤 항목. 빈 항목이면 free list의 다음(-1 = 없음)
        public int Generation;  // 항목을 반납할 때마다 1 증가: 낡은 핸들을 걸러 낸다
        public byte State;
    }

    private readonly Entry[] _entries;
    private readonly int[] _slotHead, _slotTail;
    private readonly Action<int>[] _callbacks;
    private readonly int _mask;
    private int _callbackCount;
    private int _freeHead;
    private int _dueHead = -1, _dueTail = -1;   // 이번 틱에 발동할 항목들(예약 순서 유지)
    private long _now;
    private int _pending;
    private bool _advancing;

    public TimerWheel(int wheelSize, int capacity, int maxCallbacks)
    {
        if (wheelSize < 2 || (wheelSize & (wheelSize - 1)) != 0) throw new ArgumentException("wheelSize must be a power of two (>= 2)", nameof(wheelSize));
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));
        if (maxCallbacks < 1) throw new ArgumentOutOfRangeException(nameof(maxCallbacks));

        _mask = wheelSize - 1;
        _slotHead = new int[wheelSize];
        _slotTail = new int[wheelSize];
        for (int s = 0; s < wheelSize; s++) { _slotHead[s] = -1; _slotTail[s] = -1; }

        _entries = new Entry[capacity];
        for (int i = 0; i < capacity; i++)
        {
            _entries[i].Generation = 1;
            _entries[i].Next = i + 1 < capacity ? i + 1 : -1;
            _entries[i].Prev = -1;
        }
        _freeHead = 0;
        _callbacks = new Action<int>[maxCallbacks];
    }

    public long CurrentTick => _now;
    public int PendingCount => _pending;

    public int RegisterCallback(Action<int> callback)
    {
        if (callback == null) throw new ArgumentNullException(nameof(callback));
        if (_callbackCount == _callbacks.Length) throw new InvalidOperationException("callback table is full");
        _callbacks[_callbackCount] = callback;
        return _callbackCount++;
    }

    public bool TrySchedule(int delayTicks, int callbackId, int payload, out TimerHandle handle)
    {
        if (delayTicks < 1) throw new ArgumentOutOfRangeException(nameof(delayTicks));
        if ((uint)callbackId >= (uint)_callbackCount) throw new ArgumentOutOfRangeException(nameof(callbackId));
        if (_freeHead < 0) { handle = default; return false; }

        int i = _freeHead;
        ref Entry e = ref _entries[i];          // _entries는 크기가 바뀌지 않으므로 ref를 들고 있어도 안전하다
        _freeHead = e.Next;
        e.DueTick = _now + delayTicks;
        e.CallbackId = callbackId;
        e.Payload = payload;
        e.State = InSlot;
        int s = (int)(e.DueTick & _mask);
        Append(ref _slotHead[s], ref _slotTail[s], i);
        _pending++;
        handle = new TimerHandle(i, e.Generation);
        return true;
    }

    public bool IsPending(TimerHandle handle)
    {
        return (uint)handle.Index < (uint)_entries.Length
            && handle.Generation != 0
            && _entries[handle.Index].Generation == handle.Generation
            && _entries[handle.Index].State != Free;
    }

    public bool Cancel(TimerHandle handle)
    {
        if (!IsPending(handle)) return false;
        int i = handle.Index;
        if (_entries[i].State == InSlot)
        {
            int s = (int)(_entries[i].DueTick & _mask);
            Unlink(ref _slotHead[s], ref _slotTail[s], i);
        }
        else
        {
            Unlink(ref _dueHead, ref _dueTail, i);   // 이번 틱에 발동을 기다리던 항목도 취소된다
        }
        Release(i);
        return true;
    }

    public void Advance(int ticks)
    {
        if (ticks < 0) throw new ArgumentOutOfRangeException(nameof(ticks));
        if (_advancing) throw new InvalidOperationException("Advance cannot be called from a timer callback");
        _advancing = true;
        try
        {
            for (int t = 0; t < ticks; t++)
            {
                _now++;
                int s = (int)(_now & _mask);

                // 1단계: 이번 틱 만기 항목만 슬롯에서 떼어 발동 목록으로 옮긴다(같은 슬롯의 다음 바퀴 항목은 남는다).
                //        이 단계에서는 콜백을 부르지 않으므로 미리 읽어 둔 next가 무효해질 일이 없다.
                int i = _slotHead[s];
                while (i >= 0)
                {
                    int next = _entries[i].Next;
                    if (_entries[i].DueTick == _now)
                    {
                        Unlink(ref _slotHead[s], ref _slotTail[s], i);
                        _entries[i].State = InDue;
                        Append(ref _dueHead, ref _dueTail, i);
                    }
                    i = next;
                }

                // 2단계: 발동 목록의 머리에서 하나씩 꺼내 부른다. 콜백이 목록을 바꿔도(취소) 매번 머리를 다시 읽으므로 안전하다.
                while (_dueHead >= 0)
                {
                    int k = _dueHead;
                    Unlink(ref _dueHead, ref _dueTail, k);
                    int callbackId = _entries[k].CallbackId;
                    int payload = _entries[k].Payload;
                    Release(k);   // 콜백 전에 반납: 핸들은 무효가 되고, 콜백이 이 자리를 재예약에 쓸 수 있다
                    _callbacks[callbackId](payload);
                }
            }
        }
        finally
        {
            _advancing = false;
        }
    }

    private void Release(int i)
    {
        ref Entry e = ref _entries[i];
        e.State = Free;
        e.Generation = e.Generation == int.MaxValue ? 1 : e.Generation + 1;
        e.Prev = -1;
        e.Next = _freeHead;
        _freeHead = i;
        _pending--;
    }

    private void Append(ref int head, ref int tail, int i)
    {
        _entries[i].Prev = tail;
        _entries[i].Next = -1;
        if (tail >= 0) _entries[tail].Next = i; else head = i;
        tail = i;
    }

    private void Unlink(ref int head, ref int tail, int i)
    {
        int prev = _entries[i].Prev, next = _entries[i].Next;
        if (prev >= 0) _entries[prev].Next = next; else head = next;
        if (next >= 0) _entries[next].Prev = prev; else tail = prev;
        _entries[i].Prev = -1;
        _entries[i].Next = -1;
    }
}

