public static class __Judge
{
    // 케이스마다 별도 스레드에서 실행하고 1.5초 안에 끝나지 않으면 시간 초과로 처리한다(끊어진 연결 리스트의 무한 루프 대비).
    static void Run(string id, System.Func<string> body)
    {
        string err = null;
        var worker = new System.Threading.Thread(() =>
        {
            try { err = body(); }
            catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + " " + e.Message; }
        });
        worker.IsBackground = true;
        worker.Start();
        if (!worker.Join(1500)) err = "1.5초 안에 끝나지 않음(무한 루프: 연결 리스트나 free list가 끊겼거나 순환하는지 확인)";
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Expect(string what, string expected, string actual)
    {
        return expected == actual ? null : what + ": 기대 [" + expected + "] / 결과 [" + actual + "]";
    }

    static string Join(System.Collections.Generic.List<string> xs) { return string.Join(",", xs); }

    // 기준 모델: 대기 중인 타이머를 예약 순서대로 들고 있다가 틱마다 전부 훑는다(느리지만 명백히 맞다).
    sealed class RefTimer { public long Due; public int Payload; public bool Alive; }

    public static void Main()
    {
        Run("fires-on-due-tick-fifo", () =>
        {
            var w = new TimerWheel(8, 16, 4);
            var log = new System.Collections.Generic.List<string>();
            int cb = w.RegisterCallback(p => log.Add(w.CurrentTick + ":" + p));
            w.TrySchedule(3, cb, 1, out _); w.TrySchedule(1, cb, 2, out _); w.TrySchedule(3, cb, 3, out _); w.TrySchedule(5, cb, 4, out _);
            if (w.PendingCount != 4) return "예약 4개 뒤 PendingCount 기대 4 / 결과 " + w.PendingCount;
            w.Advance(1);
            string e = Expect("Advance(1) 뒤 발동 기록(틱:payload)", "1:2", Join(log)); if (e != null) return e;
            w.Advance(2);
            e = Expect("Advance(2) 뒤(같은 틱은 예약 순서)", "1:2,3:1,3:3", Join(log)); if (e != null) return e;
            w.Advance(10);
            e = Expect("Advance(10) 뒤", "1:2,3:1,3:3,5:4", Join(log)); if (e != null) return e;
            if (w.CurrentTick != 13 || w.PendingCount != 0) return "CurrentTick 13, PendingCount 0 기대 / 결과 " + w.CurrentTick + ", " + w.PendingCount;
            return null;
        });

        Run("long-delay-wraps-wheel", () =>
        {
            var w = new TimerWheel(4, 16, 1);
            var log = new System.Collections.Generic.List<string>();
            int cb = w.RegisterCallback(p => log.Add(w.CurrentTick + ":" + p));
            foreach (int d in new[] { 14, 2, 10, 6, 3, 4, 8 }) w.TrySchedule(d, cb, d, out _); // 2·6·10·14는 같은 슬롯
            for (int t = 0; t < 15; t++) { w.Advance(1); w.Advance(0); }
            string e = Expect("크기 4 휠, 지연 14·2·10·6·3·4·8을 한 틱씩 진행", "2:2,3:3,4:4,6:6,8:8,10:10,14:14", Join(log)); if (e != null) return e;
            log.Clear();
            w.TrySchedule(37, cb, 37, out _);
            w.Advance(100);
            return Expect("틱 15에서 지연 37 예약 뒤 Advance(100)", "52:37", Join(log)) ?? (w.CurrentTick == 115 ? null : "CurrentTick 기대 115 / 결과 " + w.CurrentTick);
        });

        Run("cancel-and-stale-handles", () =>
        {
            var w = new TimerWheel(8, 1, 1);
            var log = new System.Collections.Generic.List<string>();
            int cb = w.RegisterCallback(p => log.Add(w.CurrentTick + ":" + p));
            if (!w.TrySchedule(5, cb, 1, out var h1)) return "빈 휠(용량 1)에 TrySchedule이 false";
            if (w.TrySchedule(1, cb, 2, out var full)) return "용량 1이 찼는데 TrySchedule이 true";
            if (w.IsPending(full) || w.Cancel(full) || w.Cancel(default(TimerHandle))) return "실패한 예약의 핸들이나 default 핸들이 대기 중으로 취급됨";
            if (!w.Cancel(h1)) return "대기 중인 타이머 Cancel이 false";
            if (w.IsPending(h1) || w.Cancel(h1)) return "취소한 핸들이 여전히 대기 중이거나 두 번째 Cancel이 true";
            if (w.PendingCount != 0) return "취소 뒤 PendingCount 기대 0 / 결과 " + w.PendingCount;
            if (!w.TrySchedule(2, cb, 3, out var h2)) return "취소로 빈 자리에 TrySchedule이 false";
            if (w.Cancel(h1)) return "같은 자리를 재사용한 뒤 옛 핸들 h1으로 Cancel이 true(세대 검사 없음): 새 타이머가 취소됨";
            if (!w.IsPending(h2)) return "새 타이머 h2가 대기 중이 아님";
            w.Advance(10);
            string e = Expect("발동 기록", "2:3", Join(log)); if (e != null) return e;
            return w.Cancel(h2) || w.IsPending(h2) ? "이미 발동한 타이머의 핸들이 대기 중으로 취급됨" : null;
        });

        Run("cancel-inside-callback-same-tick", () =>
        {
            var w = new TimerWheel(8, 8, 1);
            var log = new System.Collections.Generic.List<string>();
            TimerHandle hB = default, hD = default;
            int cb = w.RegisterCallback(p =>
            {
                log.Add(w.CurrentTick + ":" + p);
                if (p == 1) log.Add("pendingB=" + w.IsPending(hB) + ",cancelB=" + w.Cancel(hB) + ",cancelD=" + w.Cancel(hD));
            });
            w.TrySchedule(2, cb, 1, out _); w.TrySchedule(2, cb, 2, out hB); w.TrySchedule(2, cb, 3, out _); w.TrySchedule(6, cb, 4, out hD);
            w.Advance(10);
            string e = Expect("A(1)가 같은 틱의 B(2)와 나중의 D(4)를 취소", "2:1,pendingB=True,cancelB=True,cancelD=True,2:3", Join(log)); if (e != null) return e;
            return w.PendingCount == 0 ? null : "PendingCount 기대 0 / 결과 " + w.PendingCount;
        });

        Run("reschedule-inside-callback", () =>
        {
            var w = new TimerWheel(4, 1, 2);
            var log = new System.Collections.Generic.List<string>();
            TimerHandle self = default;
            int cb = -1;
            cb = w.RegisterCallback(p =>
            {
                log.Add(w.CurrentTick + ":" + p + (w.IsPending(self) || w.Cancel(self) ? "!" : ""));
                if (p < 3 && !w.TrySchedule(3, cb, p + 1, out self)) log.Add("재예약실패");
            });
            w.TrySchedule(3, cb, 0, out self);
            w.Advance(20);
            string e = Expect("용량 1 휠에서 콜백이 자기 자신을 3틱 뒤로 재예약('!' = 자기 핸들이 아직 대기 중으로 보임)", "3:0,6:1,9:2,12:3", Join(log)); if (e != null) return e;
            var w2 = new TimerWheel(4, 4, 1);
            log.Clear();
            int cb2 = -1;
            cb2 = w2.RegisterCallback(p => { log.Add(w2.CurrentTick + ":" + p); if (p == 100) w2.TrySchedule(4, cb2, 101, out _); });
            w2.TrySchedule(3, cb2, 100, out _);
            w2.Advance(10);
            return Expect("크기 4 휠, 틱 3의 콜백이 지연 4(같은 슬롯)로 예약", "3:100,7:101", Join(log));
        });

        Run("arguments-and-reentrancy", () =>
        {
            try { new TimerWheel(6, 4, 1); return "wheelSize 6(2의 거듭제곱 아님)이 예외 없이 생성됨"; } catch (System.ArgumentException) { }
            var w = new TimerWheel(8, 4, 2);
            var log = new System.Collections.Generic.List<string>();
            int cb = w.RegisterCallback(p =>
            {
                log.Add(w.CurrentTick + ":" + p);
                if (p == 1) { try { w.Advance(1); log.Add("중첩Advance허용"); } catch (System.InvalidOperationException) { log.Add("IOE"); } }
            });
            try { w.TrySchedule(0, cb, 9, out _); return "delayTicks 0이 예외 없이 예약됨"; } catch (System.ArgumentOutOfRangeException) { }
            try { w.TrySchedule(-3, cb, 9, out _); return "delayTicks -3이 예외 없이 예약됨"; } catch (System.ArgumentOutOfRangeException) { }
            try { w.TrySchedule(1, 1, 9, out _); return "등록되지 않은 callbackId 1이 예외 없이 예약됨"; } catch (System.ArgumentOutOfRangeException) { }
            try { w.Advance(-1); return "Advance(-1)이 예외 없이 반환"; } catch (System.ArgumentOutOfRangeException) { }
            if (w.PendingCount != 0) return "실패한 예약이 PendingCount에 남음: " + w.PendingCount;
            w.TrySchedule(2, cb, 1, out _); w.TrySchedule(2, cb, 2, out _); w.TrySchedule(3, cb, 3, out _);
            w.Advance(5);
            string e = Expect("콜백 안의 Advance는 InvalidOperationException, 바깥 진행은 계속", "2:1,IOE,2:2,3:3", Join(log)); if (e != null) return e;
            return w.CurrentTick == 5 ? null : "CurrentTick 기대 5 / 결과 " + w.CurrentTick;
        });

        Run("random-vs-reference", () =>
        {
            const int W = 8, CAP = 24;
            uint seed = 4242u;
            System.Func<int, int> rnd = n => { seed = seed * 1664525u + 1013904223u; return (int)((seed >> 8) % (uint)n); };
            var ops = new System.Collections.Generic.List<int[]>(); // {종류, 값}: 0 예약(지연), 1 취소(발급 번호 시드), 2 진행(틱)
            for (int i = 0; i < 600; i++) { int k = rnd(10); ops.Add(k < 5 ? new[] { 0, 1 + rnd(3 * W) } : k < 7 ? new[] { 1, rnd(1 << 20) } : new[] { 2, rnd(2 * W) }); }

            // 실제 휠 실행
            var w = new TimerWheel(W, CAP, 1);
            var got = new System.Collections.Generic.List<string>();
            var handles = new System.Collections.Generic.List<TimerHandle>();
            int next = 0, cb = -1;
            cb = w.RegisterCallback(p =>
            {
                got.Add("F" + w.CurrentTick + ":" + p);
                if (p % 4 == 0) { bool ok = w.TrySchedule(1 + p % 19, cb, next++, out var h); handles.Add(h); got.Add("s" + ok); }
                if (p % 6 == 1 && handles.Count > 0) got.Add("c" + w.Cancel(handles[p % handles.Count]));
            });
            var states = new System.Collections.Generic.List<string>();
            foreach (var op in ops)
            {
                if (op[0] == 0) { bool ok = w.TrySchedule(op[1], cb, next++, out var h); handles.Add(h); got.Add("S" + ok); }
                else if (op[0] == 1) { if (handles.Count > 0) got.Add("C" + w.Cancel(handles[op[1] % handles.Count])); }
                else w.Advance(op[1]);
                states.Add(w.CurrentTick + "/" + w.PendingCount);
            }

            // 기준 모델 실행
            var exp = new System.Collections.Generic.List<string>();
            var all = new System.Collections.Generic.List<RefTimer>();
            long now = 0; int pending = 0, rnext = 0;
            System.Func<int, bool> sched = null;
            System.Action<int> body = null;
            sched = delay =>
            {
                var t = new RefTimer { Due = now + delay, Payload = rnext++, Alive = pending < CAP };
                all.Add(t); if (t.Alive) pending++; return t.Alive;
            };
            System.Func<int, bool> cancel = j => { var t = all[j]; if (!t.Alive) return false; t.Alive = false; pending--; return true; };
            body = p =>
            {
                exp.Add("F" + now + ":" + p);
                if (p % 4 == 0) exp.Add("s" + sched(1 + p % 19));
                if (p % 6 == 1 && all.Count > 0) exp.Add("c" + cancel(p % all.Count));
            };
            var expStates = new System.Collections.Generic.List<string>();
            foreach (var op in ops)
            {
                if (op[0] == 0) exp.Add("S" + sched(op[1]));
                else if (op[0] == 1) { if (all.Count > 0) exp.Add("C" + cancel(op[1] % all.Count)); }
                else
                {
                    for (int t = 0; t < op[1]; t++)
                    {
                        now++;
                        var due = new System.Collections.Generic.List<RefTimer>();
                        foreach (var x in all) if (x.Alive && x.Due == now) due.Add(x);
                        foreach (var x in due) { if (!x.Alive) continue; x.Alive = false; pending--; body(x.Payload); }
                    }
                }
                expStates.Add(now + "/" + pending);
            }

            for (int i = 0; i < System.Math.Min(got.Count, exp.Count); i++)
                if (got[i] != exp[i]) return "기록 " + i + "번째 기대 " + exp[i] + " / 결과 " + got[i] + " (F=발동 틱:payload, S/s=예약 결과, C/c=취소 결과; 소문자는 콜백 안)";
            if (got.Count != exp.Count) return "기록 길이 기대 " + exp.Count + " / 결과 " + got.Count;
            for (int i = 0; i < ops.Count; i++)
                if (states[i] != expStates[i]) return "연산 " + i + " 뒤 CurrentTick/PendingCount 기대 " + expStates[i] + " / 결과 " + states[i];
            return null;
        });

        Run("zero-alloc-steady-state", () =>
        {
            var w = new TimerWheel(64, 256, 2);
            var handles = new TimerHandle[256];
            long fired = 0;
            int cbA = w.RegisterCallback(p => { fired++; });
            int cbB = w.RegisterCallback(p => { fired++; if (w.TrySchedule(1 + (p & 63), cbA, p + 1, out var h)) handles[p & 255] = h; });
            uint s = 7u;
            long used = 0;
            for (int round = 0; round < 2; round++) // 0회차는 워밍업
            {
                long before = System.GC.GetAllocatedBytesForCurrentThread();
                for (int i = 0; i < 20000; i++)
                {
                    s = s * 1664525u + 1013904223u;
                    int r = (int)(s >> 8);
                    switch (r % 4)
                    {
                        case 0:
                        case 1:
                            if (w.TrySchedule(1 + (r >> 4) % 200, (r & 1) == 0 ? cbA : cbB, r & 1023, out var h)) handles[(r >> 3) & 255] = h;
                            break;
                        case 2: w.Cancel(handles[(r >> 5) & 255]); break;
                        default: w.Advance(1 + (r >> 6) % 3); break;
                    }
                }
                used = System.GC.GetAllocatedBytesForCurrentThread() - before;
            }
            if (fired == 0) return "타이머가 한 번도 발동하지 않음";
            return used == 0 ? null : "워밍업 뒤 예약·취소·진행 2만 회에 힙 할당 " + used + " B (0 B 기대)";
        });
    }
